/* ─────────────────────────────────────────────
   STACK BUILDER PREPROD (sb-*)
───────────────────────────────────────────── */
@layer components {
  .tool-pin-wrap {
    position: relative;
    min-width: 0;
    height: 100%;
  }
  .tool-pin-wrap > a {
    height: 100%;
  }
  .tool-pin-wrap--row > a {
    height: auto;
  }
  .pin-tool-button {
    align-items: center;
    background: var(--color-text);
    border: 1px solid var(--color-text);
    border-radius: var(--radius-pill);
    color: var(--color-surface);
    display: inline-flex;
    font-family: var(--font-ui);
    font-size: 0.75rem;
    font-weight: 700;
    gap: 6px;
    min-height: 34px;
    padding: 8px 11px;
    position: absolute;
    right: 12px;
    top: 12px;
    transition: background 140ms ease-out, border-color 140ms ease-out, color 140ms ease-out, transform 140ms ease-out;
    z-index: 5;
  }
  .pin-tool-button:hover {
    transform: translateY(-1px);
  }
  .pin-tool-button:active {
    transform: translateY(-1px) scale(0.97);
  }
  .pin-tool-button:focus-visible {
    outline: 2px solid var(--color-text);
    outline-offset: 3px;
  }
  .pin-tool-button--active {
    background: var(--color-surface);
    color: var(--color-text);
  }
  .pin-tool-button--compact {
    border-radius: var(--radius-pill);
