  .td-relevance-label { font-family: var(--font-ui); font-size: 12px; font-weight: 600; color: var(--color-text); }
  .td-relevance-note { font-family: var(--font-ui); font-size: 11px; color: var(--color-muted); margin-top: 1px; }

  .td-feature-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
