  /* Tab nav — strong editorial subnav */

  /* Section anchor — scroll-margin compensates the fixed header only.
     (The in-page nav is now the bottom-floating pill, not a top bar.) */
  .td-subpage-content {
    scroll-margin-top: calc(var(--navbar-h, 68px) + 24px);
