  }
  .td-editorial-overview + .td-subpage-content,
  .td-subpage-content + .td-subpage-content {
    margin-top: var(--td-chapter-gap);
  }
  .td-subpage-content > .td-section + .td-section {
    margin-top: var(--td-block-gap);
  }

  /* Guides éditoriaux couvrant l'outil */
  .td-guides-title {
    font-family: var(--font-brand);
    font-size: 22px;
    font-weight: 600;
    color: var(--color-text);
  }
  .td-guides-list {
    margin-top: 16px;
    display: grid;
    gap: 10px;
    list-style: none;
    padding: 0;
  }
  .td-guides-link {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 16px;
    padding: 14px 16px;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-sm);
    background: var(--color-bg);
