  }

  /* Hero metadata row */

  /* Editorial comparison rows (alternatives section) */
  .td-compare { display: grid; gap: 12px; }
  .td-compare-controls {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 16px;
  }
  .td-compare-grid {
    display: flex;
    gap: 12px;
    overflow-x: auto;
    padding-bottom: 6px;
    scroll-snap-type: x mandatory;
    scroll-behavior: smooth;
    scrollbar-width: none;
    overscroll-behavior-inline: contain;
    /* Cards are routinely cut mid-content by the scroll edges — fade them
       out instead of hard-cropping, so a partial card on either side reads
       as "more to scroll" rather than a broken layout. */
    -webkit-mask-image: linear-gradient(to right, transparent 0, #000 24px, #000 calc(100% - 40px), transparent 100%);
    mask-image: linear-gradient(to right, transparent 0, #000 24px, #000 calc(100% - 40px), transparent 100%);
  }
  .td-compare-grid::-webkit-scrollbar { display: none; }
  /* The card itself is just the carousel's sizing/snap unit — it renders
     the exact same ToolCardEditorial (variant="media") used everywhere
     else on the site, so it automatically gets identical anatomy, image
     radius and hover behavior instead of a hand-rolled lookalike. */
  .td-compare-card {
    position: relative;
    flex: 0 0 min(236px, 78vw);
    min-width: 0;
    scroll-snap-align: start;
  }
  .td-compare-current-badge {
    position: absolute;
    z-index: 2;
    top: 8px;
    left: 8px;
    padding: 2px 7px;
    border-radius: var(--radius-pill);
    background: var(--color-text);
    font-family: var(--font-ui);
    font-size: 9px;
    font-weight: 700;
    line-height: 1.4;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--color-surface);
    pointer-events: none;
  }
  @media (max-width: 700px) {
    .td-compare-card { flex-basis: min(226px, 82vw); }
  }

  /* Alternatives as an App Store list: squircle icon, name, one-line pitch,
     inset dividers that start after the icon, soft highlight on hover. */
  .td-alt-shelf {
    display: grid;
    grid-template-columns: 1fr;
    column-gap: 32px;
    margin: 14px -12px 0;
    padding: 0;
    list-style: none;
  }
  @media (min-width: 768px) {
    .td-alt-shelf { grid-template-columns: repeat(2, minmax(0, 1fr)); }
