  .td-alt-shelf-item:hover { background: var(--color-surface-soft); }
  .td-alt-shelf-item:active { transform: scale(0.985); }
  .td-alt-shelf-item:focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 2px; }
  .td-alt-shelf-logo {
    padding: 2px !important;
