  .td-alt-meta {
    font-family: var(--font-ui);
    font-size: 13px;
    color: var(--color-muted);
    margin-top: 2px;
  }
  .td-alt-arrow {
    width: 14px;
    height: 14px;
    color: var(--color-muted-light);
  }

  /* Lucide icons sit inline with 12px copy. */
  .td-icon-xs {
    width: 12px;
    height: 12px;
  }

  /* ── Tool chips — a wrapped row of linked tools ── */
  .td-subs {
    margin-top: 40px;
  }
  .td-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }
  .td-chip {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 8px 14px;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius);
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 500;
    color: var(--color-text);
    text-decoration: none;
    transition: border-color 140ms;
  }
  /* was two JS mouse handlers rewriting borderColor by hand */
  .td-chip:hover {
    border-color: var(--color-text);
  }
  .td-alt-row:first-child { border-top: none; }

  .td-verdict-lead {
    max-width: 760px;
    margin: 0;
    font-family: var(--font-ui);
    font-size: 17px;
    line-height: 1.55;
    color: var(--color-text);
  }

  .td-decision-flow {
    margin: var(--td-block-gap) 0 0;
    padding: 0;
    background: transparent;
  }
  .td-decision-flow-intro { padding: 0 0 30px; }
  .td-decision-flow .td-title { margin-bottom: 16px; }
  @media (max-width: 700px) {
    .td-decision-flow { margin-inline: 0; }
  }

  .td-analysis-lead {
    font-weight: 500;
    font-size: clamp(1rem, 1.2vw, 1.0625rem);
  }
  .td-analysis-paragraph {
    margin-top: 1em;
