    background: var(--color-surface-soft);
  }

  /* v2 rating: verdict header stacked full-width above the axis grid,
     instead of a narrow label column starved next to a much taller one. */
  .td-review-rationale-v2 {
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding: 24px;
    border-radius: var(--radius-lg);
    background: var(--color-surface-soft);
  }
  .td-review-verdict-header {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 10px;
  }
  .td-review-verdict-header .td-eyebrow { margin: 0; }
  .td-review-verdict-header .td-score-axis-heading { position: relative; gap: 4px; }
  .td-review-verdict-header { gap: 6px; }
  .td-review-verdict-header .td-evidence-info { position: relative; }
  .td-review-verdict-header .td-evidence-info-panel { top: calc(100% + 6px); bottom: auto; left: 0; }
  .td-review-verdict-header:has(.td-evidence-info.is-open) { padding-bottom: 128px; }
  .td-review-verdict-header .td-review-label { margin: 0; }
  @media (max-width: 640px) {
    .td-title--with-info:has(.td-evidence-info.is-open) { padding-bottom: 0; }
    .td-title--with-info > .td-evidence-info.is-open {
      display: inline-flex;
      flex-direction: column;
      vertical-align: top;
    }
    .td-title--with-info .td-evidence-info-panel {
      position: static;
      width: min(320px, calc(100vw - 80px));
      max-width: min(320px, calc(100vw - 80px));
      margin-top: 8px;
    }
    .td-review-verdict-header .td-score-axis-heading { display: inline-flex; flex-wrap: nowrap; }
    .td-review-verdict-header { position: relative; }
    .td-review-verdict-header .td-score-axis-heading,
    .td-review-verdict-header .td-evidence-info { position: static; }
    .td-review-verdict-header .td-evidence-info-panel {
      top: 30px;
      left: 0;
      width: min(320px, calc(100vw - 80px));
      max-width: min(320px, calc(100vw - 80px));
    }
    .td-review-verdict-header:has(.td-evidence-info.is-open) { padding-bottom: 140px; }
  }
  .td-review-label {
    font-family: var(--font-brand);
    font-size: 22px;
    font-weight: 600;
    letter-spacing: -0.03em;
    color: var(--color-text);
  }

  .td-related-guides { margin-top: 16px; }
  .td-related-guides-list { display: flex; flex-direction: column; gap: 6px; }
  .td-guide-link-title {
    display: -webkit-box;
    overflow: hidden;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 500;
    line-height: 1.4;
    color: var(--color-text);
  }

  /* Compact decision rail: editorial proof first, primary product action
     second, then quiet utilities and nearby alternatives. */
  .td-decision-card {
    display: grid;
    gap: 24px;
    padding: 4px 0 0 24px;
    border-left: 1px solid var(--color-border-soft);
  }
  .td-decision-verdict {
    position: relative;
    display: grid;
    grid-template-columns: 34px minmax(0, 1fr) auto;
    gap: 4px 12px;
    padding: 18px;
    border: 1px solid var(--color-border-soft);
    border-radius: var(--radius-lg);
    /* Neutral editorial surface, shared with the submission page. */
    background: var(--color-surface-soft);
    color: var(--color-text);
  }
  .td-decision-verdict-label {
    grid-column: 1 / -1;
    display: flex;
    align-items: center;
    gap: 6px;
    font-family: var(--font-ui);
    font-size: var(--tt-size-kicker);
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
  }
  .td-decision-verdict-info {
    display: inline-flex;
    color: var(--color-muted);
  }
  .td-decision-verdict-info svg { width: 13px; height: 13px; }
  .td-decision-verdict-info:hover { color: var(--color-text); }
  .td-decision-verdict-indicator {
    display: grid;
    width: 34px;
    height: 34px;
    place-items: center;
    align-self: center;
  }
  /* Real gauge: the ring's filled arc is the score itself (score / 5 of the
     circumference), not a static trend arrow in a badge. */
  .td-decision-verdict-gauge {
    width: 34px;
    height: 34px;
    transform: rotate(-90deg);
  }
  .td-decision-verdict-gauge-track,
  .td-decision-verdict-gauge-fill {
    fill: none;
    stroke-width: 3;
  }
  .td-decision-verdict-gauge-track {
    stroke: var(--color-border);
  }
  .td-decision-verdict-gauge-fill {
    stroke: hsl(var(--primary));
    stroke-linecap: round;
    transition: stroke-dashoffset 400ms cubic-bezier(0.22, 1, 0.36, 1);
