    font-family: var(--font-ui);
  }
  .td-decision-verdict-score strong {
    font-size: var(--tt-size-metric);
    line-height: 1;
    letter-spacing: -0.05em;
  }
  .td-decision-verdict-score span,
  .td-decision-verdict-copy {
    font-family: var(--font-ui);
    font-size: var(--tt-size-card-body);
    color: var(--color-muted);
  }
  .td-decision-verdict-copy { align-self: center; text-align: right; }
  .td-decision-utility-actions { display: grid; gap: 8px; }
  .td-decision-utility-actions .pin-tool-button,
  .td-decision-utility-actions > button,
  .td-decision-utility-actions > a {
    position: static;
    inset: auto;
    display: grid;
    grid-template-columns: 17px 1fr;
