    padding: 56px 0;
  }
  .sd-cta-inner {
    max-width: var(--layout-content, 1280px);
    margin: 0 auto;
    padding: 0 var(--layout-gutter, 48px);
  }

  /* ── Risk enhanced rows ──────────────────────────────────────────────────── */
  .sd-risk-enhanced-row {
    display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 24px;
    border-top: 1px solid var(--color-border); padding: 24px 0; align-items: start;
  }
  @media (max-width: 900px) { .sd-risk-enhanced-row { grid-template-columns: 1fr 1fr; } }
  @media (max-width: 640px) { .sd-risk-enhanced-row { grid-template-columns: 1fr; gap: 10px; } }
  .sd-risk-enhanced-col { }
  .sd-risk-col-label {
    font-family: var(--font-ui); font-size: 10px; font-weight: 700;
    letter-spacing: 0.1em; text-transform: uppercase; color: var(--color-muted-light);
    margin-bottom: 6px; display: block;
  }
  .sd-risk-problem-text {
    font-family: var(--font-ui); font-size: 15px; font-weight: 600;
    color: var(--color-text); letter-spacing: -0.02em; line-height: 1.3;
  }
  .sd-risk-consequence-text {
    font-family: var(--font-ui); font-size: 14px; line-height: 1.5; color: var(--color-muted);
  }
  .sd-risk-reco-text {
    font-family: var(--font-ui); font-size: 14px; line-height: 1.5; color: var(--color-text);
  }
  @media (max-width: 900px) {
    .sd-risk-enhanced-row > .sd-risk-enhanced-col:nth-child(3) { grid-column: 1 / 3; }
  }
  @media (max-width: 640px) {
    .sd-risk-enhanced-row > .sd-risk-enhanced-col:nth-child(3) { grid-column: auto; }
  }

  /* ── Alt variant cards ───────────────────────────────────────────────────── */
  .sd-alt-grid {
    display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 28px;
  }
  @media (max-width: 900px) { .sd-alt-grid { grid-template-columns: 1fr 1fr; } }
  @media (max-width: 560px) { .sd-alt-grid { grid-template-columns: 1fr; } }
  .sd-alt-card {
    border: 1px solid var(--color-border-soft); border-radius: var(--tt-surface-radius-info);
    padding: 24px; background: var(--color-surface);
    display: flex; flex-direction: column; gap: 0;
    transition: border-color 160ms, background 160ms;
  }
  .sd-alt-card:hover { border-color: var(--color-border); background: color-mix(in srgb, var(--color-surface-soft) 42%, var(--color-surface)); }
  .sd-alt-label {
    font-family: var(--font-ui); font-size: 10px; font-weight: 700;
    letter-spacing: 0.1em; text-transform: uppercase; color: var(--color-muted-light);
    display: block; margin-bottom: 8px;
  }
  .sd-alt-title {
    font-family: var(--font-ui); font-size: 16px; font-weight: 600;
    color: var(--color-text); letter-spacing: -0.02em; margin-bottom: 6px;
  }
  .sd-alt-budget {
    font-family: var(--font-ui); font-size: 13px; font-weight: 600;
    color: var(--color-muted); margin-bottom: 14px;
  }
  .sd-alt-tools {
    font-family: var(--font-ui); font-size: 13px; line-height: 1.55; color: var(--color-muted);
