    line-height: 1.4;
    font-weight: 600;
    color: var(--color-text);
    max-width: 560px;
    margin: 32px 0 0;
  }

  .home-logo-cloud {
    position: relative;
    height: clamp(400px, 42vw, 580px);
    border-radius: var(--radius-2xl);
    overflow: hidden;
    background: radial-gradient(circle at 52% 44%, rgba(255, 255, 255, 0.95) 0%, rgba(253, 252, 252, 0.96) 42%, rgba(237, 237, 232, 0.88) 100%);
    border: 1px solid var(--color-border);
    box-shadow: 0 28px 80px rgba(34, 34, 34, 0.08);
    isolation: isolate;
  }


  .home-logo-cloud::before {
    content: "";
    position: absolute;
    inset: 14px;
    border: 1px solid rgba(34, 34, 34, 0.08);
    border-radius: var(--radius-lg);
    pointer-events: none;
    z-index: 1;
  }

  .home-logo-cloud::after {
    content: "";
    position: absolute;
    width: 70%;
    height: 1px;
    left: 15%;
    top: 52%;
    background: linear-gradient(90deg, transparent, rgba(34, 34, 34, 0.16), transparent);
    transform: rotate(-12deg);
    pointer-events: none;
    z-index: 1;
  }

  .home-logo-cloud-fade {
    position: absolute;
    inset: 0;
    z-index: 2;
    pointer-events: none;
    background:
      radial-gradient(circle at 48% 52%, transparent 34%, rgba(253, 252, 252, 0.38) 76%, rgba(253, 252, 252, 0.74) 100%),
      linear-gradient(180deg, rgba(253, 252, 252, 0.5), transparent 22%, transparent 78%, rgba(237, 237, 232, 0.64));
  }

  .home-logo-cloud-axis {
    display: none;
  }

  .home-logo-cloud-item {
    position: absolute;
    z-index: 1;
    width: 58px;
    height: 58px;
    border-radius: var(--radius-lg);
    background: rgba(255, 255, 255, 0.94);
    border: 1px solid rgba(207, 207, 200, 0.95);
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    box-shadow: 0 12px 30px rgba(34, 34, 34, 0.09);
    transform: translate3d(-50%, -50%, 0);
    will-change: transform;
  }

  .home-logo-cloud-item.is-small {
    width: 46px;
    height: 46px;
    border-radius: var(--radius-lg);
  }

  .home-logo-cloud-item.is-large {
    width: 72px;
    height: 72px;
    border-radius: var(--radius-xl);
  }

  .home-logo-cloud-item.is-foreground {
    z-index: 2;
    opacity: 1;
  }

  .home-logo-cloud-item.is-mid {
    opacity: 0.92;
    z-index: 3;
  }

  .home-logo-cloud-item.is-back {
