    padding: 6px;
    gap: 4px;
  }
  .tt-pillnav--hidden {
    transform: translateX(-50%) translateY(12px);
    opacity: 0;
  }
  .tt-pillnav-logo {
    width: 44px;
    height: 44px;
    border-radius: var(--radius-md);
  }
  .tt-pillnav-item {
    height: 38px;
    padding: 0 12px;
    font-size: 12px;
  }
}

/* Respect prefers-reduced-motion */
@media (prefers-reduced-motion: reduce) {
  .tt-pillnav {
    transition: opacity 0ms;
  }
}

