/* Sprint — Workflow card grouped recommendations (2026-05-18) */

/* Decision micro-copy under the role sentence */
.sd-stack-card-decision {
  font-size: 13px;
  font-weight: 400;
  color: var(--color-muted);
  line-height: 1.55;
  margin-top: 10px;
  max-width: 340px;
}

/* Tool group container */
.sd-tool-group {
  margin-bottom: 20px;
}
.sd-tool-group:last-of-type {
  margin-bottom: 0;
}
/* Collapsed-but-present: kept in the DOM (not conditionally unmounted) so
   crawlers see the tool names/links before any "show more" click, while
   users still see the same collapsed UI until they expand. */
.sd-tool-group--collapsed {
  display: none;
}
.sd-tool-item--collapsed {
  display: none;
}

/* .sd-tool-grid — consolidee en fin de fichier (cette regle flex etait morte,
   annulee par le display:grid qui la suivait) */

/* Mobile adjustments */
@media (max-width: 768px) {
  .sd-stack-card-decision {
    max-width: 100%;
  }
}

/* Sprint — Workflow card UX hierarchy (2026-05-18) */
/* Left col typography · group pill tags · tool items · expand button placement */

/* ── Left column: title */
.sd-stack-card-title {
  font-size: clamp(1.625rem, 2.5vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.05;
  color: var(--color-text);
  margin: 0;
}

/* ── Left column: description (role) */
.sd-stack-card-role {
  margin-top: 14px;
  font-size: 17px;
  font-weight: 400;
  line-height: 1.45;
  color: var(--color-muted);
  max-width: 380px;
}

/* ── Left column: decision sentence — stronger weight, darker */
.sd-stack-card-decision {
  margin-top: 24px !important;
  font-size: 15px !important;
  font-weight: 500 !important;
  line-height: 1.5 !important;
  color: var(--color-text) !important;
  max-width: 380px !important;
}

/* ── Left column: micro-info before expand button */
.sd-stack-card-micro {
  margin-top: 14px;
  font-size: 12px;
  font-weight: 400;
  line-height: 1.4;
  color: var(--color-muted-light);
}

/* ── Expand button: positioned after micro-info in left col */
.sd-stack-card-left .sd-expand-btn {
  margin-top: 10px;
}

/* ── Group pill tag (replaces .sd-tool-group-label block style) */
.sd-group-tag {
  display: inline-flex;
  align-items: center;
  height: 24px;
  padding: 0 10px;
  margin-bottom: 14px;
  font-family: var(--font-ui);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-muted);
  background: transparent;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
}

/* ── Tool item: flex row, no outer card */
.sd-tool-item {
  display: flex;
  align-items: center;
  gap: 14px;
  text-decoration: none;
  color: var(--color-text);
  min-width: 0;
}
.sd-tool-item:hover .sd-tool-logo {
  border-color: var(--color-muted-light);
}

/* ── Logo container: single shell — 56×56, radius 16 */
.sd-tool-logo {
  width: 56px;
  height: 56px;
  min-width: 56px;
  border-radius: var(--radius-lg);
  background: #F5F5F0; /* neutral — prevents blank-white flash during logo load */
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  overflow: hidden;
  transition: border-color 120ms ease;
}
/* Strip ToolLogo's own ring/radius/padding — the shell handles all that */
.sd-tool-logo img,
.sd-tool-logo svg {
  width: 34px !important;
  height: 34px !important;
  min-width: 34px !important;
  min-height: 34px !important;
  object-fit: contain;
  display: block;
  border-radius: 0 !important;
  background: #F5F5F0 !important; /* match shell bg — no blank-white flash */
  box-shadow: none !important;
  padding: 0 !important;
  outline: none !important;
}

/* ── Tool name */
.sd-tool-name {
  font-family: var(--font-ui);
  font-size: 17px;
  font-weight: 650;
  line-height: 1.15;
  letter-spacing: -0.025em;
  color: var(--color-text);
  max-width: 180px;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

/* ── Space between tool groups */
.sd-tool-group + .sd-tool-group {
  margin-top: 28px;
}

/* ── Mobile */
@media (max-width: 768px) {
  .sd-stack-card-role,
  .sd-stack-card-decision {
    max-width: 100%;
  }
  .sd-tool-logo {
    width: 48px;
    height: 48px;
    min-width: 48px;
    border-radius: var(--radius-lg);
  }
  .sd-tool-logo img,
  .sd-tool-logo svg {
    width: 28px !important;
    height: 28px !important;
    min-width: 28px !important;
    min-height: 28px !important;
  }
  .sd-tool-name {
    font-size: 15px;
    max-width: 150px;
  }
}

/* Sprint — Hero fact sheet typography scale (2026-05-18) */

/* Table container */
.sd-hero-fact-table {
  display: grid;
  grid-template-columns:
    minmax(220px, 1.2fr)    /* PROFIL */
    minmax(150px, 0.65fr)   /* BUDGET */
    minmax(90px,  0.42fr)   /* OUTILS */
    minmax(130px, 0.55fr)   /* NIVEAU */
    minmax(300px, 1.45fr)   /* WORKFLOW */
    minmax(260px, 1.2fr);   /* POINT D'ATTENTION */
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

/* All cells: overflow protection */
.sd-fact-col {
  min-width: 0;
  padding: 24px 24px;
}

/* Labels — all columns */
.sd-fact-label {
  display: block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-muted);
  margin-bottom: 14px;
  line-height: 1;
}

/* ── Metric values (Budget, Outils, Niveau) ── */
.sd-fact-col--compact .sd-fact-value {
  font-size: clamp(1.5rem, 2vw, 2rem); /* 24–32px */
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.045em;
  color: var(--color-text);
  white-space: nowrap;
}

/* ── Descriptive values (Profil, Workflow, Point d'attention) ── */
.sd-fact-col--long .sd-fact-value {
  font-size: clamp(1.0625rem, 1.1vw, 1.25rem); /* 17–20px */
  font-weight: 600;
  line-height: 1.22;
  letter-spacing: -0.025em;
  color: var(--color-text);
  overflow-wrap: anywhere;
  word-break: normal;
}

/* ── Budget split composition ── */
.sd-budget-composition {
  display: inline-flex;
  align-items: baseline;
  gap: 3px;
  white-space: nowrap;
}
.sd-budget-main {
  font-size: clamp(1.5rem, 2vw, 2rem); /* 24–32px */
  font-weight: 700;
  letter-spacing: -0.05em;
  line-height: 1;
  color: var(--color-text);
}
.sd-budget-unit {
  font-size: 14px;
  font-weight: 500;
  letter-spacing: -0.01em;
  line-height: 1;
  color: var(--color-muted);
}

/* ── Responsive ── */

/* 3×2 at 1024–1279px */
@media (max-width: 1279px) and (min-width: 1025px) {
  .sd-hero-fact-table {
    grid-template-columns: 1fr 1fr 1fr;
  }
}

/* 2 columns at ≤1024px */
@media (max-width: 1024px) {
  .sd-hero-fact-table {
    grid-template-columns: 1fr 1fr;
    border-radius: var(--radius-lg);
  }
}

/* Single column at ≤420px */
@media (max-width: 420px) {
  .sd-hero-fact-table {
    grid-template-columns: 1fr;
    border-radius: var(--radius-md);
  }
}

/* Sprint — Budget decision module (2026-05-18) */

/* Threshold strip */
.sd-budget-thresholds {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
