  justify-content: center;
  padding: 80px 24px;
}
.cp-not-found-inner {
  max-width: 560px;
}
.cp-not-found-inner .cp-eyebrow {
  display: block;
  margin-bottom: 16px;
}
.cp-not-found-title {
  font-family: var(--font-brand);
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 700;
  letter-spacing: -0.055em;
  line-height: 1.0;
  color: var(--color-text);
  margin: 0 0 20px;
}
