  line-height: 1.55;
  letter-spacing: -0.015em;
  color: var(--color-muted);
  margin: 0 0 32px;
  max-width: 480px;
}

/* ── Spinner keyframe (used in loading state) ──────────────────── */
@keyframes spin {
  to { transform: rotate(360deg); }
}

/* ── Skip-to-content accessibility link ───────────────────────── */
.skip-to-content {
  position: fixed;
  top: -100%;
  left: 16px;
  z-index: 9999;
  padding: 10px 18px;
  background: var(--color-text);
  color: var(--color-surface);
  font-family: var(--font-ui, system-ui, sans-serif);
  font-size: 13px;
  font-weight: 600;
  border-radius: 0 0 var(--radius) var(--radius);
  text-decoration: none;
  transition: top 0.12s ease;
}
.skip-to-content:focus-visible {
  top: 0;
  outline: 2px solid var(--color-surface);
  outline-offset: -4px;
}

/* ─────────────────────────────────────────────────────────────────────────
   Footer — editorial dark slab (Committed color strategy)
   ─────────────────────────────────────────────────────────────────────────
   Quiet utility footer. It continues the page instead of turning into a
   decorative closing slab: light surface, compact type and deliberate air.
   The hierarchy follows the restrained information density used by the
   OpenAI reference while keeping ToolTrim's own navigation and product CTA.
   ───────────────────────────────────────────────────────────────────────── */
.tt-footer {
  color: var(--tt-footer-text);
  padding: clamp(64px, 6vw, 88px) 0 0;
  margin-top: var(--tt-footer-margin-top, clamp(72px, 8vw, 128px));
}
.tt-footer-container {
  max-width: var(--layout-content, 1280px);
  margin: 0 auto;
  padding: 0 var(--layout-gutter, 48px);
}

/* ── 1. Baseline ────────────────────────────────────────── */
.tt-footer-tagline {
  margin: 0 0 var(--space-md);
  font-family: var(--font-brand);
  font-size: clamp(30px, 3.2vw, 44px);
  font-weight: 600;
  letter-spacing: -0.04em;
  line-height: 1.05;
  color: var(--tt-footer-text);
}
.tt-footer-intro {
  margin: 0;
  max-width: 56ch;
  font-family: var(--font-ui);
  font-size: var(--tt-size-body);
  line-height: 1.55;
  letter-spacing: -0.015em;
  color: var(--tt-footer-muted);
}
.tt-footer-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--space-sm);
  flex-wrap: wrap;
}
.tt-footer-action {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-xs);
  padding: 0 20px;
  border: 1px solid var(--tt-footer-border);
  border-radius: var(--radius-pill);
  font-family: var(--font-ui);
  font-size: var(--tt-size-fact-compact);
  font-weight: 600;
  line-height: 1;
  text-decoration: none;
  transition: background-color 180ms cubic-bezier(0.25, 1, 0.5, 1),
              color 180ms cubic-bezier(0.25, 1, 0.5, 1),
              border-color 180ms cubic-bezier(0.25, 1, 0.5, 1);
}
.tt-footer-action svg {
  width: 15px;
  height: 15px;
  flex: 0 0 auto;
}
.tt-footer-action--primary {
  color: var(--color-hover-text);
  background: var(--tt-footer-text);
  border-color: var(--tt-footer-text);
}
.tt-footer-action--primary:hover {
  background: var(--color-hover-strong);
  border-color: var(--color-hover-strong);
}
.tt-footer-action--secondary {
  color: var(--tt-footer-text);
  background: transparent;
}
.tt-footer-action--secondary:hover {
  color: var(--tt-footer-text);
  background: var(--color-surface-soft);
  border-color: var(--color-border);
}

/* ── 2. Link columns ────────────────────────────────────── */
.tt-footer-col {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.tt-footer-col-label {
  font-family: var(--font-ui);
  font-size: var(--tt-size-fact-compact);
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--tt-footer-muted);
  margin-bottom: 4px;
}
.tt-footer-col a {
  font-family: var(--font-ui);
  font-size: var(--tt-size-fact-compact);
  font-weight: 450;
  letter-spacing: -0.01em;
  color: var(--tt-footer-text);
  text-decoration: underline;
  text-decoration-color: transparent;
  text-underline-offset: 4px;
  text-decoration-thickness: 1px;
  transition: color 180ms cubic-bezier(0.25, 1, 0.5, 1),
              text-decoration-color 180ms cubic-bezier(0.25, 1, 0.5, 1);
}
.tt-footer-col a:hover {
  color: var(--color-text-strong);
  text-decoration-color: var(--color-text-strong);
}

/* ── 3. Quiet legal rail ────────────────────────────────── */
.tt-footer-partners {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
  padding: 12px 0 24px;
  border-top: 1px solid var(--tt-footer-border);
}
.tt-footer-partners-label {
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--tt-footer-muted);
  white-space: nowrap;
}
.tt-footer-badges {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 18px;
}
.tt-footer-badge {
  display: block;
  line-height: 0;
  opacity: 0.45;
  filter: grayscale(1);
  transition: opacity 180ms cubic-bezier(0.25, 1, 0.5, 1),
              filter 180ms cubic-bezier(0.25, 1, 0.5, 1);
}
.tt-footer-badge:hover,
.tt-footer-badge:focus-visible {
  opacity: 1;
  filter: grayscale(0);
}
.tt-footer-badge img {
  display: block;
  width: auto;
  height: 18px;
  border: 0;
}
.tt-footer-legal {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
  font-family: var(--font-ui);
  font-size: var(--tt-size-fact-compact);
  font-weight: 450;
  letter-spacing: -0.01em;
  color: var(--tt-footer-muted);
}
.tt-footer-legal a {
  color: var(--tt-footer-muted);
  text-decoration: underline;
  text-decoration-color: transparent;
  text-underline-offset: 3px;
  text-decoration-thickness: 1px;
  transition: color 180ms cubic-bezier(0.25, 1, 0.5, 1),
              text-decoration-color 180ms cubic-bezier(0.25, 1, 0.5, 1);
}
.tt-footer-legal a:hover {
  color: var(--tt-footer-text);
  text-decoration-color: var(--tt-footer-text);
}

/* ── Responsive ────────────────────────────────────────── */
@media (max-width: 900px) {
  .tt-footer-actions {
    justify-content: flex-start;
  }
}
@media (max-width: 560px) {
  .tt-footer-actions {
    align-items: stretch;
    flex-direction: column;
  }
  .tt-footer-action {
    width: 100%;
  }
  .tt-footer-legal {
    align-items: flex-start;
    flex-direction: column;
    gap: 10px;
  }
  .tt-footer-partners {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
  }
}

/* Sous-page d'un besoin — rôles visibles et cartes d'outils lisibles. */
.stack-role-section-grid {
  align-items: start;
  display: grid;
  gap: 22px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.stack-role-section {
  --stack-role-tint: #ded2ff;
  background: color-mix(in srgb, var(--stack-role-tint) 28%, var(--color-surface));
  border: 1px solid color-mix(in srgb, var(--stack-role-tint) 72%, var(--color-border));
  border-radius: var(--radius-xl);
  display: grid;
  gap: 0;
  grid-column: span 4;
  margin: 0;
  min-width: 0;
  overflow: hidden;
}
.stack-role-section--sparse {
  grid-column: span 2;
}
.stack-role-section--single {
  grid-column: span 1;
}
.stack-role-section:nth-child(4n + 2) {
  --stack-role-tint: #c9eddf;
}
.stack-role-section:nth-child(4n + 3) {
  --stack-role-tint: #cbe7f5;
}
.stack-role-section:nth-child(4n + 4) {
  --stack-role-tint: #f1dfc4;
}
.stack-role-section-head {
  align-items: center;
  background: transparent;
  display: flex;
  gap: 10px;
  justify-content: space-between;
  min-height: 50px;
  padding: 13px 16px 7px;
}
.stack-role-section-head h2 {
  font-family: var(--font-ui);
  margin: 0;
}
.stack-role-section-head h2 {
  color: var(--color-text);
  font-size: 1rem;
  font-weight: 850;
  letter-spacing: -0.018em;
}
.stack-role-section-head > span {
  color: color-mix(in srgb, var(--color-text) 62%, var(--color-muted));
  flex: 0 0 auto;
  font-family: var(--font-ui);
  font-size: 0.64rem;
  font-weight: 760;
  white-space: nowrap;
}
.stack-role-tool-grid {
  background: transparent;
  display: grid;
  gap: 14px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  padding: 8px 16px 16px;
}
.stack-role-section--sparse .stack-role-tool-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.stack-role-section--single .stack-role-tool-grid {
  grid-template-columns: minmax(0, 1fr);
}
.stack-role-tool-card {
  height: 176px;
  min-width: 0;
  position: relative;
}
.stack-objective-detail--editing .stack-role-tool-card .tce-card {
  animation: stack-tool-edit-wiggle 420ms ease-in-out infinite alternate;
  pointer-events: none;
  transform-origin: 50% 55%;
}
.stack-objective-detail--editing .stack-role-tool-card {
  cursor: grab;
}
.stack-objective-detail--editing .stack-role-tool-card:active {
  cursor: grabbing;
}
.stack-objective-detail--editing .stack-role-tool-card.is-dragging .tce-card {
  animation-play-state: paused;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-text) 18%, transparent);
  opacity: 0.72;
}
.stack-objective-detail--editing .stack-role-tool-card:nth-child(even) .tce-card {
  animation-delay: -210ms;
}
.stack-role-tool-remove {
  align-items: center;
  appearance: none;
  background: var(--color-text);
  border: 2px solid var(--color-surface);
  border-radius: var(--radius-pill);
  color: var(--color-bg);
  cursor: pointer;
  display: inline-flex;
  height: 38px;
  justify-content: center;
  padding: 0;
  position: absolute;
  right: -8px;
  top: -8px;
  transition: background 140ms ease, transform 140ms ease;
  width: 38px;
  z-index: 4;
}
.stack-role-tool-remove:hover,
.stack-role-tool-remove:focus-visible {
  background: #9a2f2f;
  outline: none;
  transform: scale(1.08);
}
.stack-role-tool-drag-handle {
  align-items: center;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  bottom: 8px;
  color: var(--color-text);
  display: inline-flex;
  height: 30px;
  justify-content: center;
  pointer-events: none;
  position: absolute;
  right: 8px;
  width: 30px;
  z-index: 3;
}
.stack-board-organize-destinations {
  align-items: center;
  background: color-mix(in srgb, var(--color-bg) 92%, transparent);
  backdrop-filter: blur(12px);
  display: flex;
  gap: 12px;
  margin: 0 0 8px;
  min-width: 0;
  padding: 6px 0 10px 16px;
  position: sticky;
  top: 0;
  z-index: 7;
}
.stack-board-organize-destinations > span {
  color: var(--color-muted);
  flex: 0 0 auto;
  font-family: var(--font-ui);
  font-size: 0.7rem;
  font-weight: 760;
}
.stack-board-organize-destinations > div {
  display: flex;
  gap: 7px;
  min-width: 0;
  overflow-x: auto;
  padding: 2px 16px 2px 0;
  scrollbar-width: none;
}
.stack-board-organize-destinations > div::-webkit-scrollbar {
  display: none;
}
.stack-board-organize-destinations button {
  appearance: none;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text);
  cursor: pointer;
  flex: 0 0 auto;
  font-family: var(--font-ui);
  font-size: 0.68rem;
  font-weight: 760;
  min-height: 34px;
  padding: 0 12px;
  transition: background 140ms ease, border-color 140ms ease, transform 140ms ease;
}
.stack-board-organize-destinations button[aria-disabled="true"] {
  color: var(--color-muted);
  cursor: default;
}
.stack-board-organize-destinations button.is-over,
.stack-board-organize-destinations button:not([aria-disabled="true"]):hover,
.stack-board-organize-destinations button:focus-visible {
  background: var(--color-text);
  border-color: var(--color-text);
  color: var(--color-bg);
  outline: none;
