}
.tce-compact-description {
  color: color-mix(in srgb, var(--color-text) 76%, var(--color-muted));
  display: -webkit-box;
  font-size: 0.76rem;
  font-weight: 540;
  line-height: 1.35;
  margin: 8px 0 0;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}
.tce-context-role {
  display: grid;
  font-family: var(--font-ui);
  gap: 1px;
