/* Fiche outil pleine page dans Ma stack. */
.stack-objective-detail--tool-page {
  display: block;
  max-width: none;
  padding-left: 0;
  padding-right: 0;
  padding-top: 0;
  position: relative;
}
.stack-objective-detail--tool-page .stack-tool-stage {
  background: transparent;
  border: 0;
  border-radius: 0;
  height: auto;
  max-height: none;
  min-height: 0;
  margin: 0 auto;
  max-width: calc(var(--layout-content, 1280px) + var(--layout-gutter, 48px) + var(--layout-gutter, 48px));
  overflow: visible;
  padding-left: var(--layout-gutter, 48px);
  padding-right: var(--layout-gutter, 48px);
  position: static;
  width: 100%;
}
.stack-tool-profile {
  display: grid;
  gap: 30px 34px;
  grid-template-areas:
    "topbar topbar"
    "hero sidebar"
    "content sidebar";
  grid-template-columns: minmax(0, 1fr) 320px;
  min-width: 0;
  width: 100%;
}
.stack-tool-profile-topbar {
  align-items: center;
  display: grid;
  gap: 20px;
  grid-template-areas:
    "context aside"
    "navigation navigation";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-area: topbar;
  min-height: 118px;
  padding-top: 26px;
  position: static;
}
.stack-tool-profile-topbar-context {
  display: block;
  grid-area: context;
  min-width: 0;
}
.stack-tool-profile-topbar-aside {
  grid-area: aside;
}
.stack-tool-profile-back {
  align-items: center;
  appearance: none;
  background: var(--color-surface-soft);
  border: 0;
  border-radius: var(--radius-pill);
  color: var(--color-text);
  cursor: pointer;
  display: inline-flex;
  font-family: var(--font-ui);
  height: 48px;
  justify-content: center;
  left: 16px;
  padding: 0;
  position: absolute;
  top: 48px;
  transition: background 140ms ease, transform 140ms ease;
  width: 48px;
}
.stack-tool-profile-back:hover,
.stack-tool-profile-back:focus-visible {
  background: color-mix(in srgb, var(--color-surface-soft) 72%, var(--color-border));
