/* ─────────────────────────────────────────────────────────────────────────
   Shared page hero — used by ToolsPage, StacksPage, ComparesIndexPage,
   GuidesPage (and any future index/listing page). One visual contract so the
   "explore" landings read as part of the same product.
   ─────────────────────────────────────────────────────────────────────────
   Legacy variants:
   - .tt-page-hero-search   → text filter on older pages
   - .tt-page-hero-cta      → CTA group on Contact and legacy pages
   Each variant slots after the desc; the surrounding shell is identical.
   ───────────────────────────────────────────────────────────────────────── */
/* Typography harmonized with the webapp shell's own hero (.hv2-*): Inter
   Tight throughout, Light/Regular weights, #222222 — a compact page header
   instead of the old Uncut-Sans marketing display type. Padding trimmed to
   match the shell's tighter vertical rhythm now that a persistent top bar
   already anchors the page, rather than a floating overlay navbar. */
.tt-page-hero {
  background: var(--color-bg);
  padding: 48px 0 40px;
}

/* Canonical page grid: every index/listing page uses this exact horizontal
   track so hero banners, filters, cards and content sections share one axis. */
.tt-page-grid,
.tt-page-hero-inner,
.tt-catalog-container,
.cix-container,
.gi-container,
.sk-container {
  width: 100%;
  max-width: var(--layout-content, 1280px);
  margin: 0 auto;
  padding-left: var(--layout-gutter, 48px);
  padding-right: var(--layout-gutter, 48px);
}
.tt-page-hero-eyebrow {
  display: block;
  font-family: var(--font-ui);
  font-size: var(--tt-size-kicker);
  font-weight: 400;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-text);
  margin-bottom: 14px;
}
.tt-page-hero-title {
  font-family: var(--font-ui);
  font-size: clamp(32px, 3.5vw, 48px);
  font-weight: 300;
  letter-spacing: -0.03em;
  line-height: 1.1;
  color: var(--color-text);
  margin: 0 0 16px;
  max-width: 22ch;
}
.tt-page-hero-desc {
  font-family: var(--font-ui);
  font-size: var(--tt-size-body-large);
  line-height: 1.5;
  letter-spacing: -0.015em;
  color: var(--color-text);
  max-width: 56ch;
  margin: 0 0 32px;
}

/* ── Banner variant: index pages ── */
.tt-page-hero--banner {
  background: var(--color-bg);
  padding: 28px 0 24px;
}
.tt-page-hero--banner .tt-page-hero-band {
  position: relative;
  overflow: hidden;
  min-height: 340px;
  display: flex;
  align-items: center;
  border: 1px solid color-mix(in oklch, var(--color-border) 68%, transparent);
  border-radius: var(--radius-xl);
  background: #f2efe7;
}
.tt-page-hero--banner .tt-page-hero-band::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(90deg, rgba(246, 243, 235, 0.98) 0%, rgba(246, 243, 235, 0.86) 34%, rgba(246, 243, 235, 0.22) 64%, rgba(246, 243, 235, 0) 100%);
  pointer-events: none;
}
.tt-page-hero--banner .tt-page-hero-art {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: right center;
}
.tt-page-hero--banner .tt-page-hero-content {
  position: relative;
  z-index: 2;
  width: min(100%, 660px);
  padding: 44px 48px;
}
.tt-page-hero-breadcrumb {
  margin-bottom: 14px;
}
.tt-page-hero--banner .tt-page-hero-eyebrow {
  margin-bottom: 12px;
}
.tt-page-hero--banner .tt-page-hero-title {
  max-width: 14ch;
  margin-bottom: 14px;
  font-size: 48px;
  font-weight: 400;
  line-height: 1.02;
  letter-spacing: 0;
}
.tt-page-hero--banner .tt-page-hero-desc {
  max-width: 44ch;
  margin-bottom: 0;
  color: color-mix(in oklch, var(--color-text) 82%, transparent);
  letter-spacing: 0;
}

@media (max-width: 1023px) {
  .tt-page-hero--banner .tt-page-hero-band {
    min-height: 320px;
  }
  .tt-page-hero--banner .tt-page-hero-content {
    width: min(100%, 600px);
    padding: 40px;
  }
  .tt-page-hero--banner .tt-page-hero-title {
    font-size: 40px;
  }
}

@media (max-width: 639px) {
  .tt-page-hero--banner {
    padding: 20px 0 18px;
  }
  .tt-page-hero--banner .tt-page-hero-band {
    min-height: 360px;
    border-radius: var(--radius-lg);
  }
  .tt-page-hero--banner .tt-page-hero-band::before {
    background: linear-gradient(180deg, rgba(246, 243, 235, 0.98) 0%, rgba(246, 243, 235, 0.9) 54%, rgba(246, 243, 235, 0.22) 100%);
  }
  .tt-page-hero--banner .tt-page-hero-art {
    object-position: center bottom;
  }
  .tt-page-hero--banner .tt-page-hero-content {
    padding: 32px 22px;
  }
  .tt-page-hero--banner .tt-page-hero-title {
    font-size: 32px;
  }
  .tt-page-hero--banner .tt-page-hero-desc {
    font-size: 16px;
  }
}

/* ── Variant: search ── */
.tt-page-hero-search {
  max-width: 640px;
}
.tt-page-hero-search-label {
  display: block;
  font-family: var(--font-ui);
  font-size: var(--tt-size-kicker);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-muted);
  margin-bottom: 10px;
}
.tt-page-hero-search-field {
  position: relative;
  display: flex;
  align-items: stretch;
  border-bottom: 2px solid var(--color-border-strong);
  transition: border-color 180ms cubic-bezier(0.25, 1, 0.5, 1);
}
.tt-page-hero-search-field:focus-within {
  border-color: var(--color-text-strong);
}
.tt-page-hero-search-input {
  flex: 1;
  height: 52px;
  padding: 0 4px;
  background: transparent;
  border: none;
  outline: none;
  font-family: var(--font-ui);
  font-size: var(--tt-size-body-large);
  font-weight: 500;
  letter-spacing: -0.015em;
  color: var(--color-text-strong);
}
.tt-page-hero-search-input::placeholder {
  color: var(--color-muted-light);
  font-weight: 400;
}
.tt-page-hero-search-clear {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  align-self: center;
  background: transparent;
  border: none;
  font-size: 22px;
  line-height: 1;
  color: var(--color-muted);
  cursor: pointer;
  border-radius: var(--radius-circle);
  transition: background 140ms ease-out, color 140ms ease-out;
}
.tt-page-hero-search-clear:hover {
  background: var(--color-surface-soft);
  color: var(--color-text);
}

/* ── Variant: CTA group (Stacks-style) ── */
.tt-page-hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  margin-top: 8px;
}

/* Shares the canonical horizontal grid above; only vertical rhythm is local. */
.tt-catalog-container {
  padding-top: 40px;
  padding-bottom: 40px;
}

/* ── Compact header (ToolsPage): replaces the tall gradient-banner hero
   with a slim breadcrumb + title so the filter bar sits close to the top —
   the catalog's own filters/results are the content, not the banner. ── */
.tt-catalog-compact-header {
  margin-bottom: 20px;
}
.tt-catalog-compact-header .cp-breadcrumb {
  margin-bottom: 10px;
}
.tt-catalog-compact-title {
  font-family: var(--font-ui);
  font-size: clamp(22px, 2.2vw, 28px);
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 1.15;
  color: var(--color-text);
  margin: 0;
}
.tt-catalog-compact-intro {
  max-width: 48ch;
  margin: 0;
  color: var(--color-muted);
  font-family: var(--font-ui);
  font-size: clamp(16px, 1.35vw, 19px);
  font-weight: 430;
  letter-spacing: -0.015em;
  line-height: 1.45;
}

/* ── Editorial opening: three deliberately unequal recommendations.
   This is a magazine-style entry point, not another catalogue row. ── */
.tt-editorial-opening {
  margin: clamp(34px, 4vw, 58px) 0 clamp(60px, 7vw, 96px);
}
.tt-editorial-opening-header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 32px;
  margin-bottom: clamp(24px, 3vw, 38px);
}
.tt-editorial-opening-heading {
  min-width: 0;
}
.tt-catalog-results-kicker {
  margin: 0 0 9px;
  color: var(--color-muted);
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.09em;
  line-height: 1.2;
  text-transform: uppercase;
}
.tt-editorial-opening-title {
  margin: 0;
  color: var(--color-text-strong);
  font-family: var(--font-ui);
  font-size: var(--tt-size-section-h);
  font-weight: 620;
  letter-spacing: -0.035em;
  line-height: 1.08;
}
.tt-editorial-opening-intro {
  max-width: 52ch;
  margin: 8px 0 0;
  color: var(--color-muted);
  font-family: var(--font-ui);
  font-size: 16px;
  font-weight: 430;
  letter-spacing: -0.01em;
  line-height: 1.45;
}
.tt-editorial-opening-link {
  flex: 0 0 auto;
  margin-bottom: 2px;
}
.tt-editorial-opening-link:hover svg,
.tt-editorial-opening-link:focus-visible svg {
  transform: translateX(0) translateY(3px);
}
.tt-editorial-opening-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: start;
  gap: clamp(16px, 1.7vw, 24px);
}
.tt-editorial-opening-item {
  min-width: 0;
}
.tt-editorial-opening-item .tc-image {
  aspect-ratio: 16 / 10;
}

.tt-catalog-results--after-editorial {
  padding-top: clamp(34px, 4vw, 52px);
  border-top: 1px solid var(--color-border-soft);
}
.tt-catalog-results-header {
  margin-bottom: 24px;
}
.tt-catalog-results-title {
  margin: 0;
  color: var(--color-text-strong);
  font-family: var(--font-brand);
  font-size: var(--tt-size-section-h);
  font-weight: 620;
  letter-spacing: -0.035em;
  line-height: 1.08;
}

@media (max-width: 1023px) {
  .tt-editorial-opening-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 639px) {
  .tt-editorial-opening {
    margin-top: 28px;
    margin-bottom: 56px;
  }
  .tt-editorial-opening-header {
    align-items: flex-start;
    flex-direction: column;
    gap: 14px;
  }
  .tt-editorial-opening-intro {
    max-width: 38ch;
  }
  .tt-editorial-opening-grid {
    width: calc(100% + var(--layout-gutter, 20px));
    grid-auto-columns: minmax(272px, 84vw);
    grid-auto-flow: column;
    grid-template-columns: none;
    gap: 14px;
    overflow-x: auto;
    padding: 0 var(--layout-gutter, 20px) 12px 0;
    scroll-padding-inline: 0 var(--layout-gutter, 20px);
    scroll-snap-type: x mandatory;
    scrollbar-width: none;
  }
  .tt-editorial-opening-grid::-webkit-scrollbar {
