  .sp-pitch .sp-hero-actions { align-items: stretch; }
  .sp-pitch .sp-hero-actions .sp-text-link { justify-content: center; }
  .sp-pitch .tt-button-primary, .sp-closing .tt-button-primary { white-space: normal; height: auto; padding-block: var(--space-sm); }
  .sp-closing .tt-button-primary { width: 100%; justify-content: center; }
  .sp-pitch h1 { text-wrap: pretty; }
  .sp-proof-line { grid-template-columns: minmax(0, 1fr); padding: var(--space-xs) var(--space-lg); }
  .sp-proof-line > div { grid-template-columns: 100px minmax(0, 1fr); align-items: center; padding: var(--space-md) 0; gap: var(--space-md); }
  .sp-proof-line > div + div { border-left: 0; border-top: 1px solid var(--color-border); }
  .sp-rating-proof { padding: var(--space-lg); }
  .sp-rating-example { padding: var(--space-md); }
