/* Category grid */

/* Tool grid */
/* ── V2 Featured carousel (2 rows × 4 cols) ── */

/* ── V2 New Additions — logo list 3×4 ── */

.tlp {
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  gap: 0;
  isolation: isolate;
  overflow: visible;
}

.tlp-item {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 36px;
  width: 36px;
  height: 36px;
  margin-left: -8px;
  overflow: hidden;
  border: 2px solid var(--color-surface);
  border-radius: var(--radius-pill);
  background: var(--color-surface);
  box-shadow: none;
}

.tlp-item:first-child { margin-left: 0; }

.tlp-mark {
  border: 0 !important;
  border-radius: var(--radius-pill) !important;
  background: transparent !important;
  box-shadow: none !important;
  padding: 3px !important;
}

.tlp--sm .tlp-item {
  flex-basis: 30px;
  width: 30px;
  height: 30px;
  margin-left: -7px;
}
.tlp--sm .tlp-item:first-child { margin-left: 0; }

.tlp-more {
  color: var(--color-muted);
  background: var(--color-surface-soft);
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.tlp.sk-card-tools {
  flex-wrap: nowrap;
  gap: 0;
}

/* ── Guides, App Store "Today" format ──
   One story across two thirds of the width, two more stacked on the right,
   every one with a real image. The right column is its own flex stack
   rather than grid rows shared with the feature: shared rows used to
   stretch to the feature's height and scatter the side items with gaps.
   Side images use the OG ratio (1.9:1) so tool screenshots, which carry
   text, are never cropped. */
.v2-today {
  display: grid;
  grid-template-columns: 1fr;
  gap: 36px;
}
/* Desktop: both columns share one height. The feature's image absorbs
   the difference (flex: 1, cover), so the two columns start and end on
   the same lines instead of the feature floating shorter or longer than
   the stack beside it. */
@media (min-width: 1024px) {
  .v2-today {
    grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
    align-items: stretch;
    gap: 40px;
  }
  .v2-today-card--feature .v2-today-media {
    flex: 1;
    min-height: 0;
    aspect-ratio: auto;
  }
}

.v2-today-side {
  display: flex;
  flex-direction: column;
  gap: 28px;
}
@media (min-width: 640px) and (max-width: 1023px) {
  .v2-today-side {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 24px;
  }
}

.v2-today-card {
  display: flex;
  flex-direction: column;
  gap: 14px;
  color: inherit;
  text-decoration: none;
}
.v2-today-card:focus-visible {
  outline: 2px solid var(--color-text-strong);
  outline-offset: 4px;
  border-radius: var(--radius-xl);
}

.v2-today-media {
  display: flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 1.9 / 1;
  overflow: hidden;
  border-radius: var(--radius-stack-card-mobile);
  background: var(--color-surface-soft);
  box-shadow: inset 0 0 0 1px var(--color-border-soft);
}
.v2-today-card--feature .v2-today-media {
  aspect-ratio: 16 / 9;
  border-radius: var(--radius-surface);
}
.v2-today-media img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 300ms cubic-bezier(0.16, 1, 0.3, 1);
}
.v2-today-card:hover .v2-today-media img {
  transform: scale(1.025);
}
.v2-today-fallback-logo {
  border-radius: 22% !important;
  background: var(--color-surface) !important;
  box-shadow: inset 0 0 0 1px var(--color-border) !important;
}
.v2-today-fallback {
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 600;
  color: var(--color-muted-light);
}

.v2-today-copy {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.v2-today-eyebrow {
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-muted-light);
}

.v2-today-title {
  font-family: var(--font-ui);
  font-size: 17px;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.01em;
  color: var(--color-text-strong);
  text-wrap: pretty;
}
.v2-today-card--feature .v2-today-title {
  max-width: 28ch;
  font-size: clamp(24px, 2.3vw, 32px);
  line-height: 1.15;
  letter-spacing: -0.025em;
  text-wrap: balance;
}

.v2-today-date {
  font-family: var(--font-ui);
  font-size: 13px;
  color: var(--color-muted);
}

@media (prefers-reduced-motion: reduce) {
  .v2-today-media img { transition: none; }
  .v2-today-card:hover .v2-today-media img { transform: none; }
}

/* ── Editorial universe index ──────────────────────────────────────────
   A bordered grid (thin rule lines, no card chrome) rather than a wall of
   gradient panels — the deliberate rhythm break between the homogeneous
   catalogue carousels, but typographic rather than decorative. Every cell
   gets border-right + border-bottom, the grid gets border-top + border-left,
   which draws a complete table of hairlines with no per-cell radius/shadow
   and no nth-child bookkeeping regardless of column count. */
/* App-store-style collections rather than a table: no grid lines around
   cells, whitespace between universes, and a single rule above each one.
   Two per row on desktop so each tool row has room for icon, name, take. */
.v2-shelf-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 44px;
}
@media (min-width: 1024px) {
  .v2-shelf-grid { grid-template-columns: repeat(2, 1fr); column-gap: 64px; row-gap: 52px; }
}

.home-v2 .tc-grid {
  column-gap: var(--v2-grid-gap);
  row-gap: var(--v2-grid-gap);
}

/* Each universe is a small editorial selection: a header that is itself
   the way into the category (count as quiet metadata, arrow on hover only),
   then three picked tools as store-style rows. One visible affordance per
   element instead of a CTA per row: the whole row is the link. */
.v2-shelf-cell {
  display: flex;
  flex-direction: column;
  padding-top: 20px;
  border-top: 1px solid var(--color-border);
}

/* Need header (9 Oct 2026): the name links to its category with the tool
   count as a superscript; neighbouring categories follow as quiet tags. */
.v2-shelf-cell-head {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 12px;
}
.v2-shelf-cell-title {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: inherit;
  text-decoration: none;
  border-radius: var(--radius);
}
.v2-shelf-cell-title:focus-visible {
  outline: 2px solid var(--color-text);
  outline-offset: 4px;
}
.v2-shelf-cell-name {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 20px;
  font-weight: 500;
  letter-spacing: -0.015em;
  color: var(--color-text);
}
/* The count rides on the name like an exponent. */
.v2-shelf-cell-count {
  position: relative;
  top: -0.7em;
  margin-left: 3px;
  font: 500 12px/1 var(--font-ui);
  letter-spacing: 0;
  font-variant-numeric: tabular-nums;
  color: var(--color-text-meta);
  vertical-align: baseline;
}
.v2-shelf-cell-arrow {
  width: 15px;
  height: 15px;
  flex-shrink: 0;
  color: var(--color-text);
  opacity: 0;
  transform: translateX(-4px);
  transition: opacity 180ms ease-out, transform 180ms ease-out;
}
.v2-shelf-cell-title:hover .v2-shelf-cell-arrow,
.v2-shelf-cell-title:focus-visible .v2-shelf-cell-arrow {
  opacity: 1;
  transform: none;
}
@media (hover: none) {
  .v2-shelf-cell-arrow { opacity: 0.6; transform: none; }
}
/* Neighbouring categories: hairline pills, quiet until hovered. */
.v2-shelf-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.v2-shelf-tag {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 0 12px;
  border-radius: var(--radius-pill);
  box-shadow: inset 0 0 0 1px var(--color-border);
  font: 500 13px/1 var(--font-ui);
  color: var(--color-text-secondary);
  text-decoration: none;
  transition: background-color 160ms ease-out, color 160ms ease-out, box-shadow 160ms ease-out;
}
.v2-shelf-tag:hover {
  background: var(--color-surface-soft);
  color: var(--color-text);
  box-shadow: inset 0 0 0 1px var(--color-border-strong);
}
.v2-shelf-tag:active { transform: scale(.97); }
.v2-shelf-tag:focus-visible {
  outline: 2px solid var(--color-text);
  outline-offset: 2px;
}

/* Negative side margin lets the hover highlight bleed past the text
   column, like a store list, while content stays aligned with the title. */
.v2-shelf-picks {
  display: flex;
  flex-direction: column;
  margin: 10px -12px 0;
  padding: 0;
  list-style: none;
}

.v2-shelf-pick {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 12px;
  border-radius: var(--radius-lg);
  color: inherit;
  text-decoration: none;
  transition: background 180ms ease-out, transform 120ms ease-out;
}
.v2-shelf-pick:hover {
  background: var(--color-surface-soft);
}
.v2-shelf-pick:active {
  transform: scale(0.99);
}
.v2-shelf-pick:focus-visible {
  outline: 2px solid var(--color-text-strong);
  outline-offset: 2px;
}

/* Store-style app icon: large rounded square with a hairline edge,
   overriding ToolLogo's default small tile look. */
.v2-shelf-pick-logo {
  flex-shrink: 0;
  border-radius: var(--radius-stack-logo) !important;
  background: var(--color-surface) !important;
  box-shadow: inset 0 0 0 1px var(--color-border) !important;
  transition: transform 200ms ease-out;
}
.v2-shelf-pick:hover .v2-shelf-pick-logo {
  transform: translateY(-1px) scale(1.03);
}

/* Inset divider under the text, never under the icon. It fades out under
   the hovered row and the one above it, so the highlight reads as one
   clean shape instead of being cut by rules. */
.v2-shelf-pick-copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  padding: 13px 0;
  border-bottom: 1px solid var(--color-border-soft);
  transition: border-color 180ms ease-out;
}
.v2-shelf-picks li:last-child .v2-shelf-pick-copy,
.v2-shelf-pick:hover .v2-shelf-pick-copy,
.v2-shelf-picks li:has(+ li .v2-shelf-pick:hover) .v2-shelf-pick-copy {
  border-bottom-color: transparent;
}

.v2-shelf-pick-name {
  font-family: var(--font-ui);
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--color-text-strong);
}

.v2-shelf-pick-take {
  font-family: var(--font-ui);
  font-size: 13px;
  line-height: 1.35;
  color: var(--color-muted);
}

@media (max-width: 640px) {
  .v2-shelf-pick { gap: 14px; }
  .v2-shelf-pick-copy { padding: 12px 0; }
}

@media (prefers-reduced-motion: reduce) {
  .v2-shelf-pick,
  .v2-shelf-pick-logo,
  .v2-shelf-cell-arrow { transition: none; }
  .v2-shelf-pick:active,
  .v2-shelf-pick:hover .v2-shelf-pick-logo { transform: none; }
}

/* Homepage tool cards (Tools we're watching, Works with): name on its own
   line above the category instead of sharing one row with it, where both
   got truncated ("Ani..." / "Design & Prototypir"). The icon grows to a
   40px rounded square, roughly the two-line block's height and centred on
   it (top-aligning read as sagging next to one-line names), same family as
   the universe rows and stack folders. Denser variants elsewhere on the
   site are untouched. */
.home-v2 .tce-identity-link {
  grid-template-columns: 40px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
}
/* Near full-bleed: many sources (Figma's product icons, favicons) already
   carry their own inner margin, so ToolLogo's default padding on top of it
   left the glyph at ~40% of the tile, small and lost. */
.home-v2 .tce-logo {
  padding: 2px !important;
  box-shadow: inset 0 0 0 1px var(--color-border) !important;
}
.home-v2 .tce-identity-copy {
  flex-direction: column;
  align-items: flex-start;
  gap: 1px;
}
.home-v2 .tce-name {
  max-width: 100%;
  font-size: var(--v2-type-card-title);
  font-weight: 500;
  line-height: 1.3;
}
.home-v2 .tce-category {
  max-width: 100%;
  font-size: 13px;
  font-weight: 400;
  line-height: 1.4;
}
.home-v2 .tce-category::before {
  content: none;
}

/* "Tools we're watching" puts an authored one-line reason in the category
   slot: let it wrap to two lines rather than truncate the point. */

/* Three columns, not four — six curated picks read as a stronger point of
   view with more room per card (bigger cover, less cramped reason line)
   than the same six thinned out across a four-up grid. */

@media (max-width: 860px) {
  .home-v2 {
    --v2-section-gap: 56px;
  }
}
@media (max-width: 640px) {
  .home-v2 {
    --v2-grid-gap: 16px;
    --v2-head-content-gap: 20px;
    --v2-section-gap: 48px;
  }
  .v2-catalog {
    padding-top: var(--space-2xl);
    padding-bottom: var(--space-md);
  }
  .v2-catalog-section + .v2-catalog-section {
    margin-top: var(--v2-section-gap);
  }
  .v2-container { padding: 0 var(--v2-grid-gutter); }
}

@media (prefers-reduced-motion: reduce) {
  .tt-carousel-arrow,
  .tt-carousel-pagination button::before {
    transition: none;
  }
}

/* ══════════════════════════════════════════════════════════════════════
   V2 Hero — responsive WebP artwork band + text overlay
   ══════════════════════════════════════════════════════════════════════ */
.hv2-root {
  padding: 20px 0 8px;
}

.hv2-container {
  max-width: var(--layout-content, 1280px);
  margin: 0 auto;
  padding: 0 var(--v2-grid-gutter);
}

.hv2-band {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius-2xl);
  background: var(--color-bg);
  min-height: 300px;
  display: flex;
  align-items: center;
  border: 1px solid color-mix(in oklch, var(--color-border) 60%, transparent);
}

.hv2-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: right center;
  z-index: 0;
}

.hv2-content {
  position: relative;
  z-index: 1;
  padding: 36px 0 36px var(--v2-grid-gutter);
  max-width: 820px;
}

.hv2-eyebrow {
  display: block;
  font-family: var(--font-ui);
  font-size: var(--tt-size-kicker);
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-text);
  margin-bottom: var(--space-lg);
}

.hv2-title {
  font-family: var(--font-ui);
  font-size: var(--tt-size-page-title);
  font-weight: 480;
  /* Tight but never touching (was -0.045em: letters collided at 56px). */
  letter-spacing: -0.03em;
  line-height: 1.04;
  color: var(--color-text);
  max-width: 18ch;
  margin: 0 0 var(--space-md);
  text-wrap: balance;
}

.hv2-subtitle {
  font-family: var(--font-ui);
  font-size: 16px;
  line-height: 1.5;
  color: var(--color-muted);
  max-width: 46ch;
  margin: 0 0 var(--space-xl);
}

.hv2-actions {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.hv2-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 13px 26px;
  border-radius: var(--radius-pill);
  border: 1.5px solid var(--color-text-strong);
  background: var(--color-text-strong);
  font-family: var(--font-ui);
  font-size: 14px;
  font-weight: 600;
  color: var(--color-bg);
  text-decoration: none;
  transition: background 150ms ease-out, color 150ms ease-out, opacity 150ms ease-out;
}
.hv2-cta:hover {
  background: var(--color-text-secondary);
  border-color: var(--color-text-secondary);
}
.hv2-cta:active, .hv2-cta-secondary:active { transform: scale(.98); }

.hv2-cta-secondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 13px 26px;
  border-radius: var(--radius-pill);
  /* Same secondary as the footer: white fill, hairline, quiet hover. */
  border: 1.5px solid var(--color-border);
  background: var(--color-surface);
  font-family: var(--font-ui);
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text-strong);
  text-decoration: none;
  transition: background 150ms ease-out, border-color 150ms ease-out, transform 120ms ease-out;
}
.hv2-cta-secondary:hover {
  background: var(--color-surface-soft);
  border-color: var(--color-border-strong);
}

/* The right-anchored logo cluster is baked into the responsive hero artwork (not a
   separate element), so its on-screen width only shrinks in step with the
   title once the band itself is narrow — a single 980px breakpoint left a
   wide "danger zone" (~860-1300px viewport) where the 48px title still ran
   under the logos before font-size caught up. Two extra steps close that
   gap by shrinking both font-size and the text column's max-width together. */
@media (max-width: 1320px) {
  .hv2-content { max-width: 640px; }
}
@media (max-width: 1080px) {
  .hv2-content { max-width: 480px; }
}
@media (max-width: 860px) {
  .hv2-band { min-height: 320px; }
  .hv2-bg { object-position: center; }
  .hv2-content { max-width: 100%; padding: 44px 32px; }
  .hv2-title { max-width: 19ch; }
}
@media (max-width: 640px) {
  .hv2-root { padding: 20px 0 4px; }
  .hv2-band { border-radius: var(--radius-lg); min-height: 340px; }
  .hv2-content { padding: 36px 22px; }
  .hv2-title {
    max-width: 20ch;
    font-size: clamp(32px, 9vw, 42px);
  }
}

/* ══════════════════════════════════════════════════════════════════════
   V2 Home — Discovery. One calm entry point (search, then a few
   categories, then a small sample of tools) instead of a wall of tagged
   carousels — the catalogue is large enough that it no longer needs to
   prove its size, it needs to help people use it.
   ══════════════════════════════════════════════════════════════════════ */

/* ══════════════════════════════════════════════════════════════════════
   V2 Home — Stack goals grid. Four flagship stacks, one per business
   objective (matches the /stacks facet taxonomy), each linking straight
   to its stack detail page rather than a filtered list.
   ══════════════════════════════════════════════════════════════════════ */
.sgs-root {
  padding: var(--space-3xl) 0 0;
}

.sgs-head {
  /* Same head as every home section: title, lead, link, one left edge. */
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: var(--v2-head-content-gap);
}

.sgs-lead {
  font-family: var(--font-ui);
  font-size: 14px;
  color: var(--color-muted);
  margin: 4px 0 0;
}


/* Store-style list rather than a wall of cards: a hairline above each
   stack, the whole row as the link, and one Apple cue doing the visual work,
   each stack drawn as an iOS folder holding its apps. */
.sgs-list {
  display: grid;
  grid-template-columns: 1fr;
  margin: 0;
  padding: 0;
  list-style: none;
}
@media (min-width: 1024px) {
  .sgs-list { grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 64px; }
}
.sgs-list > li {
  border-top: 1px solid var(--color-border);
}

.sgs-item {
  display: flex;
  align-items: center;
  gap: 22px;
  margin: 10px -14px;
  padding: 14px;
  border-radius: var(--radius-stack-card);
  color: inherit;
  text-decoration: none;
  transition: background 200ms ease-out, transform 120ms ease-out;
}
.sgs-item:hover {
  background: var(--color-surface-soft);
}
.sgs-item:active {
  transform: scale(0.99);
}
.sgs-item:focus-visible {
  outline: 2px solid var(--color-text-strong);
  outline-offset: 2px;
}

/* The folder: a soft squircle with the four apps on a 2x2 grid. On hover it
   turns white against the highlighted row and the apps drift apart a
   little, like a folder about to open. */
.sgs-folder {
  display: grid;
  flex-shrink: 0;
  grid-template-columns: repeat(2, 32px);
  grid-template-rows: repeat(2, 32px);
  place-content: center;
  gap: 8px;
  width: 96px;
  height: 96px;
  border-radius: 26px;
  background: var(--color-surface-soft);
  box-shadow: inset 0 0 0 1px var(--color-border-soft);
  transition: gap 260ms cubic-bezier(0.2, 0.8, 0.2, 1), background 200ms ease-out, transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.sgs-item:hover .sgs-folder {
  gap: 11px;
  background: var(--color-surface);
  transform: scale(1.03);
}

.sgs-folder-app {
  display: flex;
}

.sgs-folder-logo {
  border-radius: var(--radius-stack-pair-logo) !important;
  background: var(--color-surface) !important;
  box-shadow: inset 0 0 0 1px var(--color-border) !important;
}

.sgs-item-copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.sgs-item-objective {
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-muted-light);
}

.sgs-item-title {
  font-family: var(--font-ui);
  font-size: 19px;
  font-weight: 500;
  letter-spacing: -0.015em;
  color: var(--color-text-strong);
}

.sgs-item-subtitle {
  display: -webkit-box;
  overflow: hidden;
  font-family: var(--font-ui);
  font-size: 13.5px;
  line-height: 1.4;
  color: var(--color-muted);
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

@media (max-width: 640px) {
  .sgs-item { gap: 16px; }
  .sgs-folder {
    grid-template-columns: repeat(2, 28px);
    grid-template-rows: repeat(2, 28px);
    gap: 7px;
    width: 82px;
    height: 82px;
    border-radius: var(--radius-stack-card);
  }
  .sgs-folder-logo { width: 28px !important; height: 28px !important; min-width: 28px !important; min-height: 28px !important; }
  .sgs-item-subtitle { -webkit-line-clamp: 3; }
}

@media (prefers-reduced-motion: reduce) {
  .sgs-item, .sgs-folder { transition: none; }
  .sgs-item:active, .sgs-item:hover .sgs-folder { transform: none; }
}

/* ══════════════════════════════════════════════════════════════════════
   V2 App Shell — one continuous product surface. The sidebar structures
   navigation without enclosing the workspace in a second rounded box.
   ══════════════════════════════════════════════════════════════════════ */
.asv2-root {
  display: flex;
  height: 100vh;
  overflow: hidden;
  background: var(--color-surface);
}

.asv2-workspace {
  position: relative;
  display: flex;
  flex: 1;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  overflow: hidden;
  background: var(--color-bg);
}

/* Top row: logo, search shortcut and the collapse toggle sit together in
   one tight strip instead of the logo alone up top and a large 40px
   toggle floating over the content below it — closer to the compact
   sidebar header pattern of e.g. ChatGPT's own web app. */
.asv2-sidebar-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  height: 56px;
  margin-bottom: 10px;
  padding-inline: 7px;
}
/* Collapsed rail: the logo alone shares the topbar's 56px baseline. Search
   moves to its own row right below instead of stacking inside that same
   row — stacking pushed the logo's vertical center off the topbar's. */
.asv2-logo {
  display: flex;
  align-items: center;
  min-width: 0;
  color: var(--color-text);
  text-decoration: none;
}
.asv2-logo img {
  display: block;
  flex-shrink: 0;
}
.asv2-logo-mark {
  width: 24px;
  height: 24px;
  filter: grayscale(1) contrast(1.6);
}
.asv2-logo-full {
  display: none !important;
}
.asv2-root--sidebar-expanded .asv2-logo-mark {
  display: none;
}
.asv2-root--sidebar-expanded .asv2-logo-full {
  display: block !important;
  width: 96px;
  height: 21px;
}
.asv2-sidebar-top-actions {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
}

.asv2-topbar {
  position: relative;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 16px;
  height: 56px;
  flex-shrink: 0;
  padding: 0 20px;
  background: var(--color-surface);
  border-bottom: 1px solid color-mix(in srgb, var(--color-border-soft) 72%, transparent);
}

/* Le catalogue porte la même topbar que le reste du site : la recherche
   globale y reste accessible et le fil d'Ariane prend le relais du repérage.
   La barre de filtres n'a donc plus à réserver de place pour un CTA flottant. */
@media (min-width: 901px) and (max-width: 1400px) {
  .tt-catalog-toolbar.sk-mobile-trigger-row {
    flex-wrap: nowrap;
  }
}

.asv2-mobile-logo {
  display: none;
  align-items: center;
  flex-shrink: 0;
}
.asv2-mobile-logo img {
  display: block;
  height: 28px;
  width: 127px;
}

.asv2-search {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1 1 520px;
  height: 48px;
  min-width: 180px;
  max-width: 920px;
  padding: 0 6px 0 18px;
  border-radius: var(--radius-pill);
  border: 1px solid transparent;
  background: color-mix(in srgb, var(--color-surface) 64%, var(--color-border));
  color: color-mix(in srgb, var(--color-text) 72%, var(--color-muted));
  font-family: var(--font-ui);
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: background 140ms ease-out, box-shadow 140ms ease-out;
}
.asv2-search:hover {
  background: color-mix(in srgb, var(--color-surface) 52%, var(--color-border));
}
.asv2-search:focus-visible {
  outline: none;
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--color-text) 14%, transparent);
}
.asv2-search span { flex: 1; text-align: left; }
/* Trailing action circle — the pill's actual "submit search" affordance. */
.asv2-search span.asv2-search-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  width: 38px;
  height: 38px;
  border-radius: var(--radius-circle);
  background: var(--color-text);
  color: var(--color-bg);
  transition: background 140ms ease-out;
}
.asv2-search:hover .asv2-search-action {
  background: color-mix(in srgb, var(--color-text) 88%, var(--color-bg));
}

.asv2-kbd {
  font-family: var(--font-ui);
  font-size: 11px;
  color: var(--color-muted);
  border: 1px solid color-mix(in srgb, var(--color-border) 72%, transparent);
  border-radius: var(--radius-sm);
  padding: 3px 7px;
}

/* The per-page breadcrumb takes over the search bar's slot from the tablet
   breakpoint up; the homepage leaves it empty. Mobile always keeps the plain
   search bar (see max-width: 640px below). data-topbar-mode on .asv2-topbar
   (set in AppShellV2) picks what shows at desktop widths. */
.asv2-topbar-breadcrumb {
  display: none;
}
@media (min-width: 641px) {
  /* "pending": route hasn't registered a breadcrumb yet (still hydrating,
     or briefly between two routes). Show nothing rather than guessing —
     a blank slot for a moment beats flashing the search bar then swapping
     it out once the real breadcrumb commits. */
  .asv2-topbar[data-topbar-mode="home"] .asv2-search,
  .asv2-topbar[data-topbar-mode="breadcrumb"] .asv2-search,
  .asv2-topbar[data-topbar-mode="pending"] .asv2-search {
    display: none;
  }
  .asv2-topbar[data-topbar-mode="breadcrumb"] .asv2-topbar-breadcrumb {
    display: flex;
  }
}

/* Non-home pages: the search bar's slot is taken over by the page's
   breadcrumb once it registers itself (src/contexts/TopbarBreadcrumbContext).
   Full-text search stays one click away via the topbar search button. */
.asv2-topbar-breadcrumb {
  align-items: center;
  flex: 1 1 auto;
  gap: 8px;
  min-width: 0;
  overflow: hidden;
  font-family: var(--font-ui);
  font-size: 14px;
}
.asv2-topbar-breadcrumb > a {
  flex: 0 0 auto;
  color: color-mix(in srgb, var(--color-text) 62%, var(--color-muted));
  font-weight: 500;
  text-decoration: none;
  white-space: nowrap;
}
.asv2-topbar-breadcrumb > a:hover {
  color: var(--color-text);
  font-weight: 600;
}
.asv2-topbar-breadcrumb > span {
  flex: 0 1 auto;
  overflow: hidden;
  color: var(--color-muted);
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.asv2-topbar-breadcrumb > span:last-child {
  flex-shrink: 1;
  color: var(--color-text-strong);
  font-weight: 650;
}

.asv2-topbar-right {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-left: auto;
}


.asv2-currency-popover {
  width: 248px;
  padding: 10px;
  border-color: var(--color-border);
  border-radius: var(--radius-lg);
  background: var(--color-surface);
  color: var(--color-text);
  box-shadow: 0 18px 48px color-mix(in srgb, var(--color-text) 18%, transparent);
}

.asv2-currency-popover-title {
  margin: 2px 4px 8px;
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-muted);
}

.asv2-currency-options {
  display: grid;
  gap: 3px;
}

.asv2-currency-option {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 18px;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 48px;
  padding: 6px 9px;
  border: 0;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--color-text);
  text-align: left;
  cursor: pointer;
}

.asv2-currency-option:hover,
.asv2-currency-option:focus-visible,
.asv2-currency-option.is-selected {
  background: var(--color-surface-soft);
}

.asv2-currency-option:focus-visible {
  outline: 2px solid var(--color-text);
  outline-offset: -2px;
}

.asv2-currency-symbol {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-circle);
  font-size: 13px;
  font-weight: 650;
}

.asv2-currency-name {
  display: grid;
  gap: 1px;
  min-width: 0;
  font-family: var(--font-ui);
}

.asv2-currency-name strong {
  font-size: 13px;
  font-weight: 650;
}

.asv2-currency-name small {
  overflow: hidden;
  font-size: 11px;
  color: var(--color-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.asv2-currency-option > svg {
  width: 16px;
  height: 16px;
  justify-self: end;
}

/* « Ma stack » est une destination de navigation, pas le CTA de la page : un
   seul style partout, au niveau des utilitaires. Le bouton plein reste à
   l'action principale de chaque page (revue navigation, 9 oct. 2026). */
.asv2-topbar-cta {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  height: 34px;
  gap: 8px;
  padding: 0 16px;
  border: 1px solid var(--color-border-soft);
  border-radius: var(--radius-pill);
  background: var(--color-surface);
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  transition: border-color 140ms ease-out, background-color 140ms ease-out;
  white-space: nowrap;
}
.asv2-topbar-cta:hover {
  border-color: var(--color-muted);
  background: var(--color-surface-soft);
}
.asv2-topbar-cta-icon {
  position: relative;
  display: inline-flex;
}
.asv2-topbar-cta-badge {
  position: absolute;
  top: -7px;
  right: -9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 15px;
  height: 15px;
  padding: 0 3px;
  border-radius: var(--radius-pill);
  border: 1.5px solid var(--color-surface);
  background: var(--color-accent);
  color: #fff;
  font-family: var(--font-ui);
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
}
.asv2-sidebar {
  position: relative;
  /* Au-dessus de l'espace de travail : les infobulles de la colonne réduite
     débordent sur le contenu, et passaient sous ses cartes positionnées (il
     n'en restait qu'un liseré au bord de la colonne). */
  z-index: 30;
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 76px;
  flex-shrink: 0;
  overflow: visible;
  padding: 0 12px 14px;
  background: var(--color-surface);
  border-right: 1px solid color-mix(in srgb, var(--color-border-soft) 78%, transparent);
  transition: width 220ms cubic-bezier(0.16, 1, 0.3, 1);
}

.asv2-root--sidebar-expanded .asv2-sidebar {
  width: 228px;
}

.asv2-nav {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 2px;
  padding: 6px 0;
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-nav {
  padding-top: 0;
}

.asv2-nav-item {
  position: relative;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 44px;
  padding: 2px 5px;
  border-radius: var(--radius-md);
  color: color-mix(in srgb, var(--color-text) 78%, var(--color-muted));
  text-decoration: none;
  transition: background 140ms ease-out, color 140ms ease-out, transform 140ms ease-out;
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-nav-item {
  justify-content: center;
  gap: 0;
  padding-inline: 0;
}

.asv2-nav-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  border-radius: var(--radius-md);
  color: var(--color-muted);
  transition: background 120ms ease-out, color 120ms ease-out;
}
.asv2-nav-item:hover .asv2-nav-icon {
  background: color-mix(in srgb, var(--color-surface-soft) 72%, var(--color-surface));
  color: var(--color-text);
}
.asv2-nav-item--active .asv2-nav-icon {
  background: color-mix(in srgb, var(--color-surface-soft) 84%, var(--color-surface));
  color: var(--color-text-strong);
}
.asv2-nav-item--active:hover .asv2-nav-icon {
  background: color-mix(in srgb, var(--color-surface-soft) 84%, var(--color-surface));
}

.asv2-nav-label {
  width: 0;
  min-width: 0;
  overflow: hidden;
  opacity: 0;
  white-space: nowrap;
  font-family: var(--font-ui);
  font-size: 15px;
  font-weight: 520;
  color: color-mix(in srgb, var(--color-text) 82%, var(--color-muted));
  line-height: 1.2;
  text-align: left;
  transition: width 180ms ease-out, opacity 120ms ease-out;
}
.asv2-nav-item--active .asv2-nav-label {
  font-weight: 650;
  color: var(--color-text-strong);
}

.asv2-root--sidebar-expanded .asv2-nav-item:hover,
.asv2-root--sidebar-expanded .asv2-nav-item--active {
  background: color-mix(in srgb, var(--color-surface-soft) 88%, var(--color-surface));
}
.asv2-root--sidebar-expanded .asv2-nav-item:not(.asv2-nav-item--active):hover {
  background: color-mix(in srgb, var(--color-surface-soft) 56%, var(--color-surface));
  transform: translateX(2px);
}
.asv2-root--sidebar-expanded .asv2-nav-item .asv2-nav-icon {
  background: transparent;
}
.asv2-root--sidebar-expanded .asv2-nav-label {
  width: auto;
  opacity: 1;
}

/* In the compact rail the whole link is the hover/active pill, not only its
   glyph. The floating label keeps every destination identifiable. */
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-nav-item:hover .asv2-nav-icon,
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-nav-item:focus-visible .asv2-nav-icon,
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-nav-item--active .asv2-nav-icon {
  background: color-mix(in srgb, var(--color-surface-soft) 84%, var(--color-surface));
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-nav-item--active::before {
  position: absolute;
  top: 9px;
  bottom: 9px;
  left: -7px;
  width: 3px;
  border-radius: var(--radius-pill);
  background: var(--color-text-strong);
  content: "";
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-nav-item::after {
  position: absolute;
  left: calc(100% + 10px);
  top: 50%;
  z-index: 80;
  padding: 7px 11px;
  border-radius: var(--radius-pill);
  background: var(--color-text-strong);
  color: var(--color-bg);
  content: attr(data-tooltip);
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
  opacity: 0;
  pointer-events: none;
  transform: translate(-4px, -50%);
  transition: opacity 120ms ease-out, transform 120ms ease-out;
  white-space: nowrap;
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-nav-item:hover::after,
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-nav-item:focus-visible::after {
  opacity: 1;
  transform: translate(0, -50%);
}

.asv2-sidebar-submit {
  position: relative;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 36px;
  margin-top: 2px;
  padding: 2px 5px;
  border: 1px solid color-mix(in srgb, var(--color-border-soft) 78%, transparent);
  border-radius: var(--radius-md);
  color: var(--color-text-strong);
  text-decoration: none;
  transition: background 140ms ease-out, border-color 140ms ease-out;
}
.asv2-sidebar-submit .asv2-nav-icon {
  color: var(--color-text-strong);
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-sidebar-submit {
  padding-inline: 0;
  border-color: transparent;
}
.asv2-sidebar-submit:hover {
  background: var(--color-surface-soft);
  border-color: color-mix(in srgb, var(--color-border-soft) 40%, var(--color-text));
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-sidebar-submit:hover {
  border-color: transparent;
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-sidebar-submit:hover .asv2-nav-icon,
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-sidebar-submit:focus-visible .asv2-nav-icon {
  background: color-mix(in srgb, var(--color-surface-soft) 84%, var(--color-surface));
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-sidebar-submit::after {
  position: absolute;
  left: calc(100% + 10px);
  top: 50%;
  z-index: 80;
  padding: 7px 11px;
  border-radius: var(--radius-pill);
  background: var(--color-text-strong);
  color: var(--color-bg);
  content: attr(data-tooltip);
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
  opacity: 0;
  pointer-events: none;
  transform: translate(-4px, -50%);
  transition: opacity 120ms ease-out, transform 120ms ease-out;
  white-space: nowrap;
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-sidebar-submit:hover::after,
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-sidebar-submit:focus-visible::after {
  opacity: 1;
  transform: translate(0, -50%);
}

.asv2-sidebar-utility {
  margin-top: auto;
  padding: 10px 0 2px;
  border-top: 0;
}
.asv2-utility-actions {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.asv2-utility-item {
  position: relative;
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr) auto;
  align-items: center;
  width: 100%;
  min-height: 36px;
  padding: 1px 5px;
  border: 0;
  border-radius: var(--radius-md);
  background: transparent;
  color: color-mix(in srgb, var(--color-text) 80%, var(--color-muted));
  font-family: var(--font-ui);
  font-size: 13px;
  text-align: left;
  text-decoration: none;
  cursor: pointer;
  transition: background 140ms ease-out;
}
.asv2-utility-item:hover {
  background: color-mix(in srgb, var(--color-surface-soft) 72%, var(--color-surface));
  color: var(--color-text);
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-utility-item {
  grid-template-columns: 32px 0 0;
  justify-content: center;
  padding-inline: 0;
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-utility-item:hover,
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-utility-item:focus-visible {
  background: transparent;
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-utility-item:hover > svg,
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-utility-item:focus-visible > svg {
  background: color-mix(in srgb, var(--color-surface-soft) 84%, var(--color-surface));
  color: var(--color-text-strong);
}
.asv2-utility-item::after {
  position: absolute;
  left: calc(100% + 10px);
  top: 50%;
  z-index: 80;
  padding: 6px 10px;
  border-radius: var(--radius-pill);
  background: var(--color-text-strong);
  color: var(--color-bg);
  content: attr(data-tooltip);
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 600;
  line-height: 1;
  opacity: 0;
  pointer-events: none;
  transform: translate(-4px, -50%);
  transition: opacity 120ms ease-out, transform 120ms ease-out;
  white-space: nowrap;
}
.asv2-utility-item:hover::after,
.asv2-utility-item:focus-visible::after {
  opacity: 1;
  transform: translate(0, -50%);
}
.asv2-utility-item:focus-visible {
  outline: 2px solid var(--color-text);
  outline-offset: 2px;
}
.asv2-utility-item > svg {
  width: 16px;
  height: 16px;
  justify-self: center;
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-utility-item > svg {
  border-radius: var(--radius-md);
  transition: background 120ms ease-out, color 120ms ease-out;
}
.asv2-utility-text,
.asv2-utility-value {
  width: 0;
  overflow: hidden;
  opacity: 0;
  white-space: nowrap;
}
.asv2-utility-text {
  font-weight: 520;
}
.asv2-utility-value {
  color: var(--color-muted);
  font-size: 11px;
  font-weight: 650;
}
.asv2-theme-toggle {
  grid-template-columns: 32px minmax(0, 1fr);
}
.asv2-theme-toggle .asv2-utility-value {
  display: none;
}
.asv2-root--sidebar-expanded .asv2-utility-text,
.asv2-root--sidebar-expanded .asv2-utility-value {
  width: auto;
  opacity: 1;
}
.asv2-root--sidebar-expanded .asv2-utility-item {
  padding-right: 10px;
}
/* Base = expanded state: sits inline in .asv2-sidebar-top next to the logo
   and search shortcut, not floating over the nav below it. Collapsed mode
   (below) switches it back to an absolute, full-height edge strip — hover
   anywhere on the sidebar's right edge to reveal the expand affordance. */
.asv2-sidebar-resizer {
  position: relative;
  z-index: 60;
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--color-muted);
  cursor: pointer;
  transition: background 140ms ease-out, color 140ms ease-out;
}
.asv2-sidebar-resizer > span {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
}
.asv2-sidebar-resizer svg {
  flex: 0 0 auto;
  width: 16px;
  height: 16px;
}
.asv2-sidebar-resizer > b {
  position: absolute;
  top: 50%;
  left: calc(100% + 12px);
  width: max-content;
  padding: 12px 14px;
  border-radius: var(--radius-md);
  background: var(--color-surface-soft);
  box-shadow: 0 10px 26px color-mix(in srgb, var(--color-text) 14%, transparent);
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
  opacity: 0;
  pointer-events: none;
  transform: translate(-5px, -50%);
  transition: opacity 140ms ease-out, transform 140ms ease-out;
  white-space: nowrap;
}
.asv2-sidebar-resizer:hover,
.asv2-sidebar-resizer:focus-visible {
  background: var(--color-surface-soft);
  color: var(--color-text);
}
.asv2-sidebar-resizer:hover > b,
.asv2-sidebar-resizer:focus-visible > b {
  opacity: 1;
  transform: translate(0, -50%);
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-sidebar-resizer {
  box-shadow: none;
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-sidebar-resizer > span {
  top: 50%;
  left: 50%;
  border-radius: var(--radius-md);
  transition: opacity 140ms ease-out, transform 140ms ease-out;
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-sidebar-resizer > b {
  top: 50%;
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-sidebar-resizer:hover > span,
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-sidebar-resizer:focus-visible > span {
  opacity: 1;
}

@media (min-width: 901px) {
  .asv2-root--sidebar-expanded .asv2-utility-actions {
    flex-direction: row;
    justify-content: flex-start;
    gap: 2px;
  }
  .asv2-root--sidebar-expanded .asv2-utility-item {
    display: grid;
    flex: 0 0 auto;
    grid-template-columns: 1fr;
    min-width: 0;
    width: 36px;
    min-height: 36px;
    padding: 3px;
    border-radius: var(--radius-pill);
  }
  .asv2-root--sidebar-expanded .asv2-utility-item > svg {
    justify-self: center;
  }
  .asv2-root--sidebar-expanded .asv2-utility-text,
  .asv2-root--sidebar-expanded .asv2-utility-value {
    position: absolute;
    width: 1px;
    height: 1px;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    opacity: 0;
  }
  .asv2-root--sidebar-expanded .asv2-utility-item::after {
    left: 50%;
    top: auto;
    bottom: calc(100% + 9px);
    transform: translate(-50%, 4px);
  }
  .asv2-root--sidebar-expanded .asv2-utility-item:hover::after,
  .asv2-root--sidebar-expanded .asv2-utility-item:focus-visible::after {
    transform: translate(-50%, 0);
  }
}

.dark .asv2-logo img {
  filter: invert(1);
}
.dark .asv2-logo .asv2-logo-mark {
  filter: grayscale(1) contrast(1.6) invert(1);
}
.dark .asv2-mobile-logo img {
  filter: invert(1);
}
.dark .asv2-search {
  background: var(--color-surface-soft);
  color: var(--color-text);
}
.dark .asv2-search:hover {
  background: color-mix(in srgb, var(--color-surface-soft) 82%, var(--color-border));
}
.asv2-content {
  flex: 1;
  min-width: 0;
  height: 100%;
  overflow-x: hidden;
  overflow-y: auto;
  /* Route content can grow after a Supabase response. Never let the browser
     preserve the footer as its scroll anchor across that layout change;
     ScrollToTop owns route restoration explicitly. */
  overflow-anchor: none;
  scrollbar-gutter: stable;
  -webkit-overflow-scrolling: touch;
  background: var(--color-bg);
}

/* Preserve content width on compact laptop layouts. The control still keeps
   the user's preference, which becomes visible again at the next breakpoint. */
@media (min-width: 641px) and (max-width: 1180px) {
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-sidebar { width: 76px; }
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-logo-mark { display: block; }
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-logo-full { display: none !important; }
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-label,
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-utility-text,
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-utility-value,
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-utility-heading { display: none; }
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-utility-item { padding-right: 5px; }
  /* This range is a forced compact rail: expose the same destination pills,
     and hide the resize affordance because changing the stored desktop
     preference would have no visible effect here. */
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item:hover,
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item:focus-visible,
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item--active {
    background: color-mix(in srgb, var(--color-surface-soft) 84%, var(--color-surface));
  }
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item .asv2-nav-icon { background: transparent; }
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item::after {
    position: absolute;
    left: calc(100% + 10px);
    top: 50%;
    z-index: 80;
    padding: 7px 11px;
    border-radius: var(--radius-pill);
    background: var(--color-text-strong);
    color: var(--color-bg);
    content: attr(data-tooltip);
    font-family: var(--font-ui);
    font-size: 12px;
    font-weight: 600;
    line-height: 1;
    opacity: 0;
    pointer-events: none;
    transform: translate(-4px, -50%);
    transition: opacity 120ms ease-out, transform 120ms ease-out;
    white-space: nowrap;
  }
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item:hover::after,
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item:focus-visible::after {
    opacity: 1;
    transform: translate(0, -50%);
  }
}

@media (max-width: 640px) {
  /* Mobile keeps the normal, whole-page document scroll (the sidebar
     collapses into a horizontal tab row below the topbar, so there's no
     sidebar/content corner to preserve here) — undo the desktop
     locked-shell/internal-scroll layout used to keep that corner in view. */
  .asv2-root {
    display: block;
    height: auto;
    overflow: visible;
    padding: 0;
    background: var(--color-surface);
  }
  .asv2-workspace {
    display: block;
    overflow: visible;
    border-radius: 0;
  }
  /* overflow-x: clip, not hidden — pairing hidden with overflow-y: visible
     makes the UA silently promote that visible to auto (the overflow spec's
     rule against a clipped axis next to a scrollable one), turning this
     back into a real scroll container. That's the whole reason mobile
     stickiness broke: position: sticky was resolving against this box
     instead of the actual page scroll, since a height: auto container never
     scrolls internally. clip doesn't trigger that promotion, so overflow-y
     stays genuinely visible and .asv2-content stops being a scroll
     container at all, letting position: sticky descendants (the catalog
     toolbars) stick to the real page scroll like on desktop. */
  .asv2-content { height: auto; overflow-x: clip; overflow-y: visible; scrollbar-gutter: auto; }

  .asv2-topbar { position: sticky; top: 0; padding: 0 16px; height: 56px; gap: 12px; }
  .asv2-mobile-logo { display: flex; padding-right: 4px; }
  .asv2-search { width: auto; flex: 1; min-width: 0; height: 42px; padding: 0 4px 0 14px; }
  .asv2-kbd { display: none; }
  .asv2-topbar-cta { padding: 8px 14px; font-size: 12px; }

  .asv2-sidebar {
    display: none;
  }
}

@media (max-width: 440px) {
  .asv2-search > span:not(.asv2-search-action) { display: none; }
  .asv2-search {
    flex: 0 0 42px;
    width: 42px;
    min-width: 42px;
    max-width: 42px;
    padding: 0;
    justify-content: center;
    gap: 0;
    background: transparent;
  }
  .asv2-search span.asv2-search-action {
    width: 42px;
    height: 42px;
  }
}

/* ══════════════════════════════════════════════════════════════════════
   Mobile bottom navigation (asv2-bottomnav) — minimal
   A flat, full-width bar flush at the bottom: a subtle "Ma stack" pill
   floating above a thin divider, then a row of 5 tabs with a small top
   indicator on the active one. Desktop keeps the left sidebar.
   ══════════════════════════════════════════════════════════════════════ */
.asv2-bottomnav { display: none; }

@media (max-width: 640px) {
  /* Desktop sidebar is replaced by the mobile bottom bar */
  .asv2-topbar-cta { display: inline-flex; }
  .asv2-content { padding-bottom: calc(68px + env(safe-area-inset-bottom)); }

  .asv2-bottomnav {
    display: flex;
    align-items: stretch;
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 200;
    padding: 0 0 calc(6px + env(safe-area-inset-bottom));
    background: var(--color-surface);
    box-shadow: 0 -1px 0 var(--color-border-soft), 0 -4px 16px rgba(0, 0, 0, 0.04);
  }

  /* Subtle "Ma stack" pill, centered above the divider (like the ref chip) */
  .asv2-bn-cta {
    align-self: center;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    margin-bottom: 10px;
    padding: 8px 16px;
    border-radius: var(--radius-pill);
    background: var(--color-surface-soft);
    color: var(--color-text);
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 600;
    letter-spacing: -0.01em;
    text-decoration: none;
    transition: background 120ms ease-out;
  }
  .asv2-bn-cta:active { background: var(--color-border-soft); }

  .asv2-bn-row {
    display: flex;
    width: 100%;
    justify-content: space-around;
    align-items: stretch;
  }

  .asv2-bn-item {
    position: relative;
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 5px;
    min-height: 60px;
    padding: 9px 0 4px;
    text-decoration: none;
    color: var(--color-muted);
    transition: color 140ms ease-out;
  }
  .asv2-bn-item--active { color: var(--color-text-strong); }
  .asv2-bn-item:active { opacity: 0.55; }

  /* Small top indicator bar on the active tab (sits on the divider) */
  .asv2-bn-indicator {
    position: absolute;
    top: 0;
    width: 26px;
    height: 3px;
    border-radius: var(--radius-pill);
    background: var(--color-text-strong);
    opacity: 0;
    transition: opacity 140ms ease-out;
  }
  .asv2-bn-item--active .asv2-bn-indicator { opacity: 1; }

  .asv2-bn-label {
    font-family: var(--font-ui);
    font-size: 11px;
    font-weight: 500;
    line-height: 1;
    letter-spacing: -0.01em;
  }
  .asv2-bn-item--active .asv2-bn-label { font-weight: 650; }
}

@media (max-width: 440px) {
  .asv2-topbar-cta {
    width: 42px;
    height: 42px;
    padding: 0;
    justify-content: center;
  }
  .asv2-topbar-cta > span:not(.asv2-topbar-cta-icon) { display: none; }
}

/* ══════════════════════════════════════════════════════════════════════
   Shared filter bar (tt-filter-*) — used by ToolsPage + StacksPage
   Quick pill-selects for the 1-2 primary facets of each page. Secondary/
   long-tail facets (Stacks) live behind the "Filtres" panel trigger
   (.sk-mobile-trigger, now shown at every breakpoint, not just mobile).
   Results count + sort reuse .sk-results-header/.sk-results-count/
   .sk-results-sort so both pages share one literal set of classes there.
   ══════════════════════════════════════════════════════════════════════ */
.tt-filter-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 20px;
}
.tt-filter-select-wrap {
  position: relative;
  display: inline-flex;
}
.tt-filter-select {
  appearance: none;
  height: 38px;
  padding: 0 34px 0 16px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: -0.01em;
  cursor: pointer;
}
.tt-filter-select:hover { border-color: var(--color-text); }
.tt-filter-select:focus-visible { outline: 2px solid var(--color-border-strong); outline-offset: 2px; }
.tt-filter-select-chevron {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 13px;
  height: 13px;
  pointer-events: none;
  color: var(--color-muted);
}
.tt-filter-bar-spacer { margin-left: auto; }
.tt-filter-stack-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 38px;
  padding: 0 16px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: -0.01em;
  text-decoration: none;
  transition: border-color 150ms;
}
.tt-filter-stack-link:hover { border-color: var(--color-text); }

/* ══════════════════════════════════════════════════════════════════════
   Filter dropdown (tf-dd-*) — pill trigger + anchored popover panel.
   Shared by FilterDropdown.tsx (Catégorie, Profil, Budget) and the
   Stacks "Filtres" panel trigger (long-tail facets), so every quick
   filter on the site opens the same kind of contained popover instead
   of a native <select> or a full-screen takeover.
   ══════════════════════════════════════════════════════════════════════ */
.tf-dd-trigger {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 38px;
  padding: 0 14px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: -0.01em;
  cursor: pointer;
  transition: border-color 150ms, box-shadow 150ms;
}
.tf-dd-trigger:hover { border-color: var(--color-text); }
.tf-dd-trigger--open {
  border-color: var(--color-text);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-text) 9%, transparent);
}
.tf-dd-trigger--active { color: var(--color-text); font-weight: 600; }
.tf-dd-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: var(--radius-pill);
  background: var(--color-text-strong);
  color: var(--color-bg);
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
}
.tf-dd-chevron {
  width: 14px;
  height: 14px;
  color: var(--color-muted);
  transition: transform 150ms;
}
.tf-dd-trigger--open .tf-dd-chevron { transform: rotate(180deg); }

.tf-dd-panel {
  z-index: 1000;
  width: 280px;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow:
    0 18px 42px color-mix(in srgb, var(--color-text) 13%, transparent),
    inset 0 1px 0 color-mix(in srgb, #fff 58%, transparent);
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.tf-dd-search {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 42px;
  padding: 0 11px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
  color: var(--color-muted);
  transition: border-color 140ms ease-out, box-shadow 140ms ease-out;
}
.tf-dd-search:focus-within {
  border-color: var(--color-text);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-text) 8%, transparent);
}
.tf-dd-search input {
  flex: 1;
  min-width: 0;
  border: none;
  outline: none;
  background: transparent;
  font-family: var(--font-ui);
  font-size: 13px;
  color: var(--color-text);
}
.tf-dd-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: 288px;
  overflow-y: auto;
}
.tf-dd-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 42px;
  padding: 0 11px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: 14px;
  line-height: 1.3;
  letter-spacing: -0.01em;
  text-align: left;
  cursor: pointer;
}
.tf-dd-item:hover { background: var(--color-surface-soft); }
.tf-dd-item:focus-visible {
  outline: none;
  background: var(--color-surface-soft);
  box-shadow: inset 0 0 0 1.5px var(--color-text);
}
.tf-dd-item--active { font-weight: 600; }
.tf-dd-item--active svg { color: var(--color-text); flex-shrink: 0; }
.tf-dd-item--checkbox { justify-content: flex-start; }
.tf-dd-checkbox {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  border: 1.5px solid var(--color-border-strong);
  border-radius: var(--radius-xs);
  color: var(--color-bg);
  transition: background 120ms, border-color 120ms;
}
.tf-dd-checkbox--checked {
  background: var(--color-text-strong);
  border-color: var(--color-text-strong);
}
.tf-dd-clear {
  margin-top: 2px;
  padding: 8px 10px;
  border: none;
  border-top: 1px solid var(--color-border);
  border-radius: 0;
  background: transparent;
  color: var(--color-muted);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  text-align: center;
  cursor: pointer;
}
.tf-dd-clear:hover { color: var(--color-text); }
.tf-dd-empty {
  padding: 10px;
  font-family: var(--font-ui);
  font-size: 13px;
  color: var(--color-muted-light);
  text-align: center;
}

/* ── Stacks "Filtres" panel: anchored popover, not a full-screen takeover.
   Portaled to document.body and positioned via inline top/left (computed
   from the trigger's rect), so only width/visuals are set here. ── */
.sk-filters-panel {
  z-index: 1000;
  width: min(720px, calc(100vw - 32px));
  max-height: min(560px, calc(100vh - 140px));
  overflow-y: auto;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: 0 20px 48px rgba(18, 18, 16, 0.16);
}
.sk-filters-panel .sk-mobile-panel-header {
  position: sticky;
  top: 0;
}

/* Ma stack MVP — grille visuelle régulière inspirée des boards Pinterest. */
.stack-board-grid {
  align-items: stretch;
  gap: 16px;
  grid-auto-flow: row;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.stack-board-card {
  grid-template-rows: minmax(0, 1fr) 56px;
  height: 390px;
}
.stack-board-preview {
  gap: 14px;
  height: 100%;
  justify-content: flex-start;
  padding: 18px;
}
.stack-board-preview-copy {
  min-height: 58px;
}
.stack-board-preview-copy h2 {
  align-content: flex-start;
  font-size: clamp(1.35rem, 2vw, 1.72rem);
  line-height: 1.04;
}
.stack-board-tool-list {
  gap: 6px;
  margin-top: 0;
}
.stack-board-tool-row {
  grid-template-columns: auto minmax(0, 1fr) 28px;
  min-height: 42px;
  padding: 4px 5px 4px 7px;
}
.stack-board-auto-correction {
  align-items: center;
  border-radius: var(--radius-pill);
  display: inline-flex;
  height: 28px;
  justify-content: center;
  min-height: 28px;
  opacity: 0;
  padding: 0;
  width: 28px;
}
.stack-board-tool-row:hover .stack-board-auto-correction,
.stack-board-tool-row:focus-within .stack-board-auto-correction {
  background: rgba(255, 255, 255, 0.72);
  opacity: 1;
}
.stack-board-footer {
  min-height: 56px;
  padding: 8px 8px 0;
}
.stack-board-explore {
  font-size: 0.9rem;
}
.stack-board-explore::after {
  height: 30px;
  width: 30px;
}
.stack-board-add-link {
  border-radius: var(--radius-pill);
  height: 34px;
  min-height: 34px;
  padding: 0;
  width: 34px;
}
.stack-board-card--create .stack-board-create-preview {
  height: 100%;
  min-height: 0;
}
.stack-overview-needs-action--icon {
  border-radius: var(--radius-pill);
  min-height: 44px;
  padding: 0;
  width: 44px;
}
.stack-unassigned-card {
  gap: 10px;
}
.stack-unassigned-head {
  align-items: center;
}
.stack-unassigned-head h2 {
  font-size: 1.2rem;
}
.stack-unassigned-row {
  grid-template-columns: auto minmax(0, 1fr) 32px;
}
.stack-unassigned-organize {
  border-radius: var(--radius-pill);
  height: 32px;
  min-height: 32px;
  padding: 0;
  width: 32px;
}
.stack-visual-subdomain-grid {
  display: grid;
  gap: 18px;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}
.stack-visual-subdomain {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: grid;
  gap: 12px;
  padding: 14px;
}
.stack-visual-subdomain-head {
  align-items: center;
  display: flex;
  gap: 10px;
  justify-content: space-between;
  min-height: 32px;
}
.stack-visual-subdomain-head h2 {
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: 1rem;
  font-weight: 840;
  margin: 0;
}
.stack-visual-subdomain-head span {
  align-items: center;
  background: var(--color-bg);
  border-radius: var(--radius-pill);
  color: var(--color-muted);
  display: inline-flex;
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 800;
  height: 26px;
  justify-content: center;
  min-width: 26px;
}
.stack-visual-tool-grid {
  display: grid;
  gap: 8px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.stack-visual-tool-tile {
  background: color-mix(in srgb, var(--color-bg) 74%, var(--color-surface));
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  min-height: 100px;
  overflow: hidden;
  position: relative;
}
.stack-visual-tool-tile > a {
  align-items: center;
  color: var(--color-text);
  display: flex;
  flex-direction: column;
  font-family: var(--font-ui);
  font-size: 0.82rem;
  font-weight: 800;
  gap: 8px;
  height: 100%;
  justify-content: center;
  min-width: 0;
  padding: 14px 34px 12px 12px;
  text-align: center;
  text-decoration: none;
}
.stack-visual-tool-tile > a > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  width: 100%;
}
.stack-visual-tool-logo {
  border-radius: var(--radius) !important;
}
.stack-visual-tool-edit {
  align-items: center;
  appearance: none;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid rgba(18, 18, 16, 0.1);
  border-radius: var(--radius-pill);
  color: var(--color-muted);
  cursor: pointer;
  display: inline-flex;
  height: 28px;
  justify-content: center;
  opacity: 0;
  padding: 0;
  position: absolute;
  right: 7px;
  top: 7px;
  width: 28px;
