  }
  .stack-objective-hero-inner {
    gap: 12px;
  }
  .stack-objective-hero-round {
    height: 44px;
    width: 44px;
  }
  .stack-objective-hero-copy h1 {
    font-size: 1.75rem;
    line-height: 1.02;
    overflow: visible;
    text-overflow: clip;
