/* Explorer — exploration contextuelle transversale. */
.ex-page { margin: 0 auto; max-width: 1440px; min-width: 0; padding: 24px var(--layout-gutter, 48px) 96px; }
.ex-page--tool { display: block; }
.ex-tool-stage {
  display: grid;
  margin-bottom: 18px;
}
.ex-tool-stage > .ex-tool-focus { margin: 0; width: 100%; }
.ex-page--tool > .ex-grid { margin-top: 0; }
.ex-page--tool > .ex-empty { margin: 48px auto; }
.ex-source-banner {
  align-items: center; background: color-mix(in srgb, var(--color-bg) 94%, transparent); backdrop-filter: blur(16px);
  border: 1px solid color-mix(in srgb, var(--color-border) 78%, transparent); border-radius: var(--radius-xl);
  display: grid; gap: 14px; grid-template-columns: auto minmax(0, 1fr) auto; margin-bottom: 24px;
  padding: 14px; position: sticky; top: 12px; z-index: 12;
}
.ex-source-banner--objective {
  backdrop-filter: none;
  background: transparent;
  border: 0;
  border-radius: 0;
  grid-template-columns: 1fr auto 1fr;
  min-height: 96px;
  padding: 12px 0;
  position: relative;
  top: auto;
}
.ex-source-banner--objective > .ex-back { justify-self: start; }
.ex-objective-heading { min-width: 0; max-width: min(760px, 100%); text-align: center; }
.ex-objective-heading > span { color: var(--color-muted); display: block; font-family: var(--font-ui); font-size: var(--tt-size-kicker); font-weight: 760; margin-bottom: 6px; text-transform: uppercase; }
.ex-objective-heading h1 {
  overflow-wrap: anywhere;
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: var(--tt-size-page-title);
  font-weight: 850;
  letter-spacing: -.045em;
  line-height: 1;
  margin: 0;
}
.ex-tag-filter {
  backdrop-filter: blur(18px);
  background: color-mix(in srgb, var(--color-bg) 97%, transparent);
  grid-column: 1 / -1;
  isolation: isolate;
  margin-inline: calc(var(--layout-gutter, 48px) * -1);
  min-width: 0;
  padding: 14px var(--layout-gutter, 48px) 0;
  position: sticky;
  top: 0;
  z-index: 45;
}
.ex-tag-filter-sentinel { display: block; height: 1px; margin-bottom: -1px; pointer-events: none; }
.ex-page:not(.ex-page--tool) > .ex-tag-filter { margin-bottom: 16px; }
.ex-tag-filter-surface {
  align-items: center;
  display: flex;
  gap: 0;
  max-width: 100%;
  padding: 0 0 14px;
  width: 100%;
}
.ex-tag-filter.is-pinned .ex-tag-filter-surface { gap: 18px; }
.ex-tag-filter-scroll { flex: 1 1 auto; min-width: 0; position: relative; }
.ex-tag-filter-track {
  align-items: center;
  display: flex;
  gap: 10px;
  min-width: 0;
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  scrollbar-width: none;
  scroll-padding-inline: 2px;
  scroll-snap-type: inline proximity;
  touch-action: pan-x;
  width: 100%;
}
.ex-tag-filter-track::-webkit-scrollbar { display: none; }
.ex-filter-context {
  align-items: center;
  display: flex;
  flex: 0 0 auto;
  gap: 11px;
  max-width: 0;
  opacity: 0;
  overflow: hidden;
  padding-right: 2px;
  pointer-events: none;
  transform: translateX(-10px);
  transition: max-width 220ms cubic-bezier(.22,1,.36,1), opacity 150ms ease, transform 220ms cubic-bezier(.22,1,.36,1);
  white-space: nowrap;
}
.ex-tag-filter.is-pinned .ex-filter-context { max-width: 290px; opacity: 1; pointer-events: auto; transform: translateX(0); }
.ex-filter-context-back {
  align-items: center;
  appearance: none;
  background: var(--color-surface-soft);
  border-radius: var(--radius-circle);
  color: var(--color-text);
  cursor: pointer;
  display: inline-flex;
  height: 38px;
  justify-content: center;
  padding: 0;
  width: 38px;
}
.ex-filter-context-back:hover { transform: translateX(-1px); }
.ex-filter-context-back:focus-visible { outline: 3px solid color-mix(in srgb, var(--color-text) 22%, transparent); outline-offset: 2px; }
.ex-filter-context-copy { display: grid; gap: 1px; min-width: 0; }
.ex-filter-context-copy small {
  color: var(--color-muted);
  font-family: var(--font-ui);
  font-size: var(--tt-size-kicker);
  font-weight: 680;
  line-height: 1;
}
.ex-filter-context-copy strong {
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: var(--tt-size-card-body);
  font-weight: 820;
  line-height: 1.1;
  max-width: 140px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ex-filter-context-divider { background: var(--color-border); height: 32px; margin-left: 5px; width: 1px; }
.ex-tag-filter-item {
  align-items: center;
  appearance: none;
  background: transparent;
  border-radius: var(--radius-pill);
  color: var(--color-text);
  cursor: pointer;
  display: inline-flex;
  flex: 0 0 auto;
  font-family: var(--font-ui);
  font-size: var(--tt-size-card-body);
  font-weight: 760;
  letter-spacing: -.015em;
  min-height: 44px;
  padding: 0 17px;
  scroll-snap-align: start;
  transition: background 140ms ease, color 140ms ease;
  white-space: nowrap;
}
.ex-tag-filter-item:hover {
  background: color-mix(in srgb, var(--color-surface-soft) 68%, transparent);
}
.ex-tag-filter-item.is-active {
  background: var(--color-surface-soft);
  color: var(--color-text);
  font-weight: 820;
}
.ex-tag-filter-item.is-active:hover { background: color-mix(in srgb, var(--color-surface-soft) 88%, var(--color-border)); }
.ex-tag-filter-item:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--color-text) 22%, transparent);
  outline-offset: 2px;
}
.ex-tag-filter-control {
  align-items: center;
  appearance: none;
  background: var(--color-surface-soft);
  border-radius: var(--radius-circle);
  color: var(--color-text);
  cursor: pointer;
  display: inline-flex;
  height: 34px;
  justify-content: center;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 34px;
  z-index: 2;
}
.ex-tag-filter-control--left { left: 0; }
.ex-tag-filter-control--right { right: 0; }
.ex-tag-filter-control:hover { background: var(--color-border); }
.ex-tag-filter-control:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--color-text) 22%, transparent);
  outline-offset: 2px;
}
.ex-results-heading {
  align-items: end;
  display: flex;
  gap: 24px;
  justify-content: space-between;
  margin: 8px 0 20px;
  padding-top: 24px;
}
.ex-results-heading > div { display: grid; gap: 7px; min-width: 0; }
.ex-results-heading h2 {
  color: var(--color-text);
  font-family: var(--font-brand);
  font-size: var(--tt-size-section-h);
  font-weight: 600;
  letter-spacing: -.04em;
  line-height: 1.05;
  margin: 0;
}
.ex-results-heading p {
  color: var(--color-muted);
  flex: 0 0 auto;
  font-family: var(--font-ui);
  font-size: var(--tt-size-card-body);
