}
@keyframes ex-tool-focus-enter {
  from { opacity: .7; transform: scale(.985); }
  to { opacity: 1; transform: scale(1); }
}
.ex-tool-focus {
  animation: ex-tool-focus-enter 190ms cubic-bezier(.22,1,.36,1) both;
  background: color-mix(in srgb, var(--color-surface-soft) 60%, var(--color-surface));
  border-radius: var(--radius-2xl);
  margin: 0 auto 28px;
  overflow: hidden;
  transform-origin: 50% 20%;
  width: 100%;
}
.ex-tool-focus-main {
  display: grid;
  align-items: center;
  gap: 32px;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  padding: 18px;
}
/* Reuses the shared .tc-image cover/fallback logic (OG image when large
   enough to be a real screenshot, centered logo otherwise) — these overrides
   only adapt the box to the hero's bigger, borderless layout. */
.ex-tool-focus-visual.tc-image {
  align-items: center;
  aspect-ratio: 1200 / 630;
  border: 0;
  border-radius: var(--radius-lg);
  display: flex;
  justify-content: center;
