.stack-tool-add-page.stack-board-card--design { --stack-destination-color: #def0fb; }
.stack-tool-add-page.stack-board-card--automation { --stack-destination-color: #ffe3cf; }
.stack-tool-add-page.stack-board-card--marketing { --stack-destination-color: #f8e2ef; }
.stack-tool-add-page.stack-board-card--vente { --stack-destination-color: #e5ecff; }
.stack-tool-add-page.stack-board-card--finance { --stack-destination-color: #e3f0dc; }
.stack-tool-add-page.stack-board-card--dev { --stack-destination-color: #e8e0ff; }
.stack-tool-add-page.stack-board-card--custom { --stack-destination-color: #f3ead2; }
.stack-boards-page--motion-deeper .stack-tool-add-search-row {
  animation: stack-context-fade 150ms 55ms ease-out both;
}
.stack-boards-page--motion-deeper .stack-tool-add-results {
  animation: stack-depth-enter 190ms 70ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
  transform-origin: 50% 0;
}
.stack-boards-page--motion-deeper .stack-tool-add-footer {
  animation: stack-context-fade 150ms 90ms ease-out both;
}
.stack-tool-add-hero {
  align-items: start;
  display: grid;
  column-gap: 24px;
  grid-template-areas:
    "heading profile"
    "destination actions";
  grid-template-columns: minmax(0, 1fr) minmax(218px, 260px);
  min-height: 168px;
  padding: 26px 0 30px;
  position: relative;
  row-gap: 20px;
}
.stack-tool-add-profile {
  grid-area: profile;
  justify-self: end;
}
.stack-tool-add-destination-card {
  align-items: flex-end;
  align-self: stretch;
  background: var(--stack-destination-color);
  border-radius: var(--radius-lg);
  display: flex;
  grid-area: destination;
  justify-content: space-between;
  justify-self: start;
  margin: 0;
  min-height: 72px;
  overflow: hidden;
  padding: 14px;
  position: relative;
  width: 260px;
}
.stack-tool-add-destination-card::after {
  background: color-mix(in srgb, var(--color-text) 8%, transparent);
  border-radius: var(--radius-pill);
  content: "";
  height: 96px;
  position: absolute;
  right: -34px;
  top: -46px;
  width: 96px;
}
.stack-tool-add-destination-copy {
  display: grid;
  gap: 4px;
  min-width: 0;
  position: relative;
  z-index: 1;
}
.stack-tool-add-destination-copy strong {
  color: var(--color-text);
  font: 850 1.08rem/1 var(--font-ui);
  letter-spacing: -0.035em;
}
.stack-tool-add-destination-copy small {
  color: color-mix(in srgb, var(--color-text) 66%, var(--color-muted));
  font: 740 0.66rem/1 var(--font-ui);
}
.stack-tool-add-destination-logos {
  align-items: center;
  display: flex;
  margin-left: 12px;
  position: relative;
  z-index: 1;
}
.stack-tool-add-destination-logos > span {
  align-items: center;
  background: rgba(255, 255, 255, 0.82);
  border: 2px solid rgba(255, 255, 255, 0.88);
  border-radius: var(--radius-pill);
  display: inline-flex;
  height: 36px;
  justify-content: center;
  overflow: hidden;
  width: 36px;
}
.stack-tool-add-destination-logos > span + span { margin-left: -9px; }
.stack-tool-add-back {
  align-items: center;
  appearance: none;
  background: var(--color-surface-soft);
  border: 0;
  border-radius: var(--radius-pill);
  color: var(--color-text);
  cursor: pointer;
  display: inline-flex;
  height: 48px;
  justify-content: center;
  left: calc(-1 * var(--stack-leading-gutter, 80px) + 16px);
  padding: 0;
  position: absolute;
  top: 48px;
  width: 48px;
}
.stack-tool-add-back:hover,
.stack-tool-add-back:focus-visible {
  background: color-mix(in srgb, var(--color-surface-soft) 72%, var(--color-border));
  outline: none;
}
.stack-tool-add-heading {
  align-self: start;
  display: grid;
  gap: 8px;
  grid-area: heading;
  min-width: 0;
}
.stack-tool-add-heading h1 {
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: clamp(2rem, 3.4vw, 3.1rem);
  font-weight: 880;
  letter-spacing: -0.052em;
  line-height: 0.98;
  margin: 0 0 -0.1em;
  max-width: 24ch;
  overflow: visible;
  padding-bottom: 0.1em;
  text-overflow: clip;
  white-space: normal;
}
.stack-tool-add-done {
  grid-area: actions;
  justify-self: end;
}
.stack-tool-add-heading p {
  align-items: center;
  color: var(--color-muted);
  display: flex;
  flex-wrap: wrap;
  font-family: var(--font-ui);
  font-size: 0.78rem;
  gap: 7px;
  margin: 0;
}
.stack-tool-add-heading p span {
  background: var(--color-surface-soft);
  border-radius: var(--radius-xs);
  color: var(--color-text);
  font-weight: 760;
  padding: 3px 7px;
}
.stack-tool-add-heading p strong {
  font-weight: 680;
}
.stack-tool-add-done,
.stack-tool-add-footer button {
  align-items: center;
  appearance: none;
  background: var(--color-text);
  border: 0;
  border-radius: var(--radius-pill);
  color: var(--color-bg);
  cursor: pointer;
  display: inline-flex;
  font-family: var(--font-ui);
  font-size: 0.78rem;
  font-weight: 820;
  gap: 8px;
  min-height: 46px;
  padding: 0 17px;
  white-space: nowrap;
}
.stack-tool-add-done > span,
.stack-tool-add-footer button > span {
  align-items: center;
  background: var(--color-bg);
  border-radius: var(--radius-pill);
  color: var(--color-text);
  display: inline-flex;
  font-size: 0.66rem;
  height: 22px;
  justify-content: center;
  min-width: 22px;
}
.stack-tool-add-search-row {
  background: color-mix(in srgb, var(--color-bg) 94%, transparent);
  backdrop-filter: blur(14px);
  padding: 0 0 18px;
  position: sticky;
  top: 0;
  z-index: 8;
}
.stack-tool-add-sticky-destination {
  align-items: center;
  display: flex;
  gap: 7px;
  min-height: 30px;
  padding: 0 2px 7px;
}
.stack-tool-add-sticky-destination > span {
  background: var(--stack-destination-color);
  border: 1px solid color-mix(in srgb, var(--color-text) 8%, transparent);
  border-radius: var(--radius-xs);
  height: 16px;
  width: 16px;
}
.stack-tool-add-sticky-destination strong,
.stack-tool-add-sticky-destination small {
  font-family: var(--font-ui);
  line-height: 1;
}
.stack-tool-add-sticky-destination strong {
  color: var(--color-text);
  font-size: 0.72rem;
  font-weight: 820;
}
.stack-tool-add-sticky-destination small {
  color: var(--color-muted);
  font-size: 0.66rem;
  font-weight: 700;
}
.stack-tool-picker-search.stack-tool-add-search {
  background: var(--color-surface-soft);
  border: 1px solid transparent;
  min-height: 54px;
  padding: 0 18px;
}
.stack-tool-picker-search.stack-tool-add-search input {
  font-size: 0.94rem;
}
.stack-tool-add-results {
  display: grid;
  gap: 18px;
  padding: 10px 0 36px;
}
.stack-tool-add-results-head {
  align-items: baseline;
  display: flex;
  justify-content: space-between;
}
.stack-tool-add-results-head h2 {
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: 1.08rem;
  font-weight: 850;
  margin: 0;
}
.stack-tool-add-results-head > span {
  color: var(--color-muted);
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 720;
}
.stack-tool-add-grid {
  display: grid;
  gap: 14px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.stack-tool-add-card {
  appearance: none;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  color: var(--color-text);
  cursor: pointer;
  display: grid;
  gap: 26px;
  min-height: 178px;
  padding: 16px;
  text-align: left;
  transition: background 140ms ease, border-color 140ms ease, transform 140ms ease;
}
.stack-tool-add-card:hover,
.stack-tool-add-card:focus-visible {
  border-color: var(--color-border-strong);
  outline: none;
  transform: translateY(-2px);
}
.stack-tool-add-card.is-adding {
  border-color: color-mix(in srgb, var(--color-text) 24%, var(--stack-destination-color));
  box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--stack-destination-color) 54%, transparent);
  cursor: default;
  transform: scale(0.985);
}
.stack-tool-add-card.is-added {
  animation: stack-tool-added 200ms cubic-bezier(0.2, 0.8, 0.2, 1);
  background: color-mix(in srgb, var(--stack-destination-color) 72%, var(--color-surface));
  border-color: color-mix(in srgb, var(--color-text) 28%, var(--stack-destination-color));
  box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--stack-destination-color) 74%, transparent);
}
.stack-tool-add-flying-tool {
  filter: drop-shadow(0 8px 12px rgba(34, 34, 34, 0.18));
  margin: 0 !important;
  pointer-events: none;
  position: fixed !important;
  transform-origin: center;
  z-index: 1000;
}
@keyframes stack-tool-added {
  0% { transform: scale(1); }
  48% { transform: scale(0.975); }
  100% { transform: scale(1); }
}
.stack-tool-add-card-top {
  align-items: flex-start;
  display: flex;
  justify-content: space-between;
}
.stack-tool-add-state {
  align-items: center;
  background: var(--color-text);
  border-radius: var(--radius-pill);
  color: var(--color-bg);
  display: inline-flex;
  height: 34px;
  justify-content: center;
  width: 34px;
}
.stack-tool-add-state.is-added {
  background: #2f7656;
  color: var(--color-surface);
  animation: stack-tool-check 200ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
@keyframes stack-tool-check {
  0% { opacity: 0; transform: scale(0.5); }
  100% { opacity: 1; transform: scale(1); }
}
@media (prefers-reduced-motion: reduce) {
  .stack-tool-add-card.is-added,
  .stack-tool-add-state.is-added {
    animation: none;
  }
}
.stack-tool-add-card-copy {
  display: grid;
  gap: 4px;
  min-width: 0;
}
.stack-tool-add-card-copy strong {
  font-family: var(--font-ui);
  font-size: 1rem;
  font-weight: 850;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.stack-tool-add-card-copy small,
.stack-tool-add-card-copy > span {
  color: var(--color-muted);
  font-family: var(--font-ui);
  font-size: 0.7rem;
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.stack-tool-add-card-copy small {
  font-weight: 760;
}
.stack-tool-add-grid > .stack-tool-picker-more {
  grid-column: 1 / -1;
  margin-top: 8px;
}
.stack-tool-add-page .stack-tool-picker-empty button {
  appearance: none;
  background: transparent;
  border: 1px solid var(--color-border-strong);
  border-radius: var(--radius-pill);
  color: var(--color-text);
  cursor: pointer;
  font: 760 0.78rem var(--font-ui);
  justify-self: center;
  min-height: 40px;
  padding: 0 16px;
}
.stack-tool-add-footer {
  align-items: center;
  background: color-mix(in srgb, var(--color-bg) 94%, transparent);
  backdrop-filter: blur(14px);
  border-top: 1px solid var(--color-border);
  bottom: 0;
  display: flex;
  gap: 20px;
  justify-content: space-between;
  margin: 28px 0 -96px;
  min-height: 78px;
  padding: 14px 0 18px;
  position: sticky;
  z-index: 9;
}
.stack-tool-add-footer > span {
  color: var(--color-muted);
  font-family: var(--font-ui);
  font-size: 0.78rem;
  font-weight: 700;
}

@media (min-width: 1600px) {
  .stack-tool-add-grid { grid-template-columns: repeat(5, minmax(0, 1fr)); }
}
@media (max-width: 1100px) {
  .stack-tool-add-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 860px) {
  .stack-tool-add-page { padding-bottom: 88px; }
  .stack-tool-add-hero {
    gap: 14px;
    grid-template-areas:
      "back heading"
      "profile profile"
      "destination destination";
    grid-template-columns: auto minmax(0, 1fr);
    min-height: 132px;
  }
  .stack-tool-add-back {
    grid-area: back;
    left: auto;
    position: static;
    transform: none;
  }
  .stack-tool-add-done { display: none; }
  .stack-tool-add-profile {
    justify-self: stretch;
    width: 100%;
  }
  .stack-tool-add-destination-card {
    border-radius: var(--radius-lg);
    margin: 12px 0;
    min-height: 106px;
    padding: 14px;
    width: 100%;
  }
  .stack-tool-add-destination-logos { display: none; }
  .stack-tool-add-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .stack-tool-add-footer { margin-bottom: -88px; }
}
@media (max-width: 560px) {
  .stack-tool-add-hero {
    align-items: center;
    column-gap: 12px;
    grid-template-areas:
      "back heading"
      "profile profile"
      "destination destination";
    grid-template-columns: 44px minmax(0, 1fr);
    padding: 12px 0 14px;
  }
  .stack-tool-add-destination-card {
    margin: 0;
    min-height: 72px;
  }
  .stack-tool-add-back {
    height: 44px;
    width: 44px;
  }
  .stack-tool-add-heading h1 { font-size: 1.75rem; line-height: 1.02; white-space: normal; }
  .stack-tool-add-grid { grid-template-columns: 1fr; }
  .stack-tool-add-card { gap: 18px; min-height: 150px; }
  .stack-tool-add-footer {
    align-items: stretch;
    bottom: calc(118px + env(safe-area-inset-bottom));
  }
  .stack-tool-add-footer > span { display: none; }
  .stack-tool-add-footer button { justify-content: center; width: 100%; }
}

/* Ma stack — cartes éditoriales colorées, proches de la référence validée. */
.stack-board-grid {
  gap: 22px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: 0;
}
.stack-board-card {
  grid-template-rows: minmax(0, 1fr) 60px;
  height: 320px;
  padding: 8px;
  position: relative;
}
.stack-board-card-open {
  appearance: none;
  background: transparent;
  border: 0;
  cursor: pointer;
  inset: 0;
  padding: 0;
  position: absolute;
  z-index: 1;
}
.stack-board-card-open:focus-visible {
  border-radius: var(--radius);
  box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--color-text) 42%, transparent);
  outline: none;
}
.stack-board-editorial-cover {
  align-items: stretch;
  appearance: none;
  border: 0;
  cursor: default;
  display: flex;
  flex-direction: column;
  gap: 18px;
  height: 100%;
  justify-content: space-between;
  padding: 22px;
  text-align: left;
  width: 100%;
}
.stack-board-editorial-cover:focus-visible {
  outline: 3px solid rgba(18, 18, 16, 0.5);
  outline-offset: -5px;
}
.stack-board-editorial-cover .stack-board-preview-copy {
  display: grid;
  gap: 14px;
  min-height: 0;
}
.stack-board-editorial-heading {
  align-items: baseline;
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
}
.stack-board-editorial-title {
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: clamp(1.65rem, 2.2vw, 2.4rem);
  font-weight: 900;
  letter-spacing: -0.055em;
  line-height: 0.94;
  max-width: 100%;
  min-width: 0;
  overflow-wrap: normal;
  word-break: normal;
}
.stack-board-editorial-heading .stack-board-title-count {
  color: color-mix(in srgb, var(--color-text) 76%, var(--color-muted));
  font-size: 0.72rem;
  font-weight: 850;
}
.stack-board-editorial-description {
  color: color-mix(in srgb, var(--color-text) 86%, var(--color-muted));
  display: block;
  font-family: var(--font-ui);
  font-size: clamp(0.82rem, 0.9vw, 0.96rem);
  font-weight: 610;
  line-height: 1.28;
  max-width: 28ch;
}
.stack-board-editorial-logos {
  align-items: center;
  display: flex;
  flex-wrap: nowrap;
  gap: 0;
  margin-top: auto;
  min-height: 54px;
  overflow: visible;
  position: relative;
}
.stack-board-editorial-logo,
.stack-board-editorial-empty {
  align-items: center;
  background: rgba(255, 255, 255, 0.78);
  border: 2px solid rgba(255, 255, 255, 0.82);
  border-radius: var(--radius-pill);
  display: inline-flex;
  flex: 0 0 auto;
  height: 54px;
  justify-content: center;
  overflow: hidden;
  width: 54px;
}
.stack-board-editorial-logo + .stack-board-editorial-logo {
  margin-left: -7px;
}
.stack-board-editorial-logo-mark {
  background: transparent !important;
  border-radius: var(--radius-pill) !important;
  box-shadow: none !important;
  padding: 0 !important;
}
.stack-board-editorial-empty {
  color: var(--color-muted);
}
.stack-board-editorial-logos .stack-board-overflow {
  aspect-ratio: 1;
  border-radius: var(--radius-circle);
  box-sizing: border-box;
  height: 50px;
  list-style: none;
  margin: 0;
  max-width: 50px;
  min-width: 50px;
  padding: 0;
  width: 50px;
}
.stack-board-editorial-logos .stack-board-overflow::-webkit-details-marker {
  display: none;
}
.stack-board-logo-more {
  flex: 0 0 50px;
  margin-left: -4px;
  position: relative;
  z-index: 8;
}
.stack-board-logo-more[open] {
  z-index: 18;
}
.stack-board-logo-popover {
  align-items: center;
  background: rgba(255, 255, 255, 0.97);
  border: 1px solid rgba(18, 18, 16, 0.12);
  border-radius: var(--radius-md);
  bottom: calc(100% + 8px);
  box-shadow: 0 14px 34px rgba(18, 18, 16, 0.16);
  display: grid;
  gap: 7px;
  grid-template-columns: repeat(3, 44px);
  max-height: 148px;
  overflow-y: auto;
  padding: 9px;
  position: absolute;
  right: 0;
}
.stack-board-logo-popover-item {
  align-items: center;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  display: inline-flex;
  height: 44px;
  justify-content: center;
  overflow: hidden;
  width: 44px;
}
.stack-board-footer {
  min-height: 60px;
  padding: 6px 8px 0;
  position: relative;
  z-index: 2;
}
.stack-board-explore {
  align-items: center;
  font-size: 0.84rem;
  gap: 7px;
}
.stack-board-explore::after {
  border-radius: var(--radius);
  font-size: 1.2rem;
  height: 38px;
  margin-left: 2px;
  width: 38px;
}
.stack-board-add-link {
  font-size: 0.8rem;
  gap: 6px;
  min-height: 40px;
  padding: 0 12px;
  width: auto;
}
.stack-board-card--unassigned .stack-board-preview {
  background: #f1ede4;
}
.stack-board-card--unassigned .stack-board-footer > span {
  color: color-mix(in srgb, var(--color-text) 62%, var(--color-muted));
}
.stack-board-grid--organizing .stack-board-card:not(.stack-board-card--create):not(.stack-board-card--unassigned) {
  cursor: grab;
}
.stack-board-grid--organizing .stack-board-card:not(.stack-board-card--create):not(.stack-board-card--unassigned):active {
  cursor: grabbing;
}
.stack-board-grid--organizing .stack-board-card:not(.stack-board-card--create):not(.stack-board-card--unassigned) > .stack-board-preview,
.stack-board-grid--organizing .stack-board-card:not(.stack-board-card--create):not(.stack-board-card--unassigned) > .stack-board-footer {
  animation: stack-board-organize-wiggle 420ms ease-in-out infinite alternate;
  transform-origin: 50% 55%;
}
.stack-board-grid--organizing .stack-board-card:nth-child(even) > .stack-board-preview,
.stack-board-grid--organizing .stack-board-card:nth-child(even) > .stack-board-footer {
  animation-delay: -210ms;
}
.stack-board-grid--organizing .stack-board-card-open,
.stack-board-grid--organizing .stack-board-footer button,
.stack-board-grid--organizing .stack-board-logo-more {
  pointer-events: none;
}
.stack-board-grid--organizing .stack-board-card.is-dragging > .stack-board-preview,
.stack-board-grid--organizing .stack-board-card.is-dragging > .stack-board-footer {
  animation-play-state: paused;
  opacity: 0.68;
}
.stack-board-grid--organizing .stack-board-card.is-drop-target {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-text) 20%, transparent);
}
.stack-board-drag-handle,
.stack-board-delete,
.stack-board-rename {
  align-items: center;
  background: rgba(255, 255, 255, 0.94);
  border: 2px solid rgba(255, 255, 255, 0.92);
  border-radius: var(--radius-pill);
  color: var(--color-text);
  display: inline-flex;
  height: 38px;
  justify-content: center;
  position: absolute;
  top: 10px;
  width: 38px;
  z-index: 12;
}
.stack-board-drag-handle {
  pointer-events: none;
  right: 10px;
}
