   New class names on purpose: the older sd-related / sg-tool layers are
   overridden several times in this file, which is what broke the cards. */
.sg-apps {
  margin: 8px -12px 0;
  padding: 0;
  list-style: none;
}
.sg-apps-item { scroll-margin-top: 90px; }
.sg-app {
  position: relative;
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr) 20px;
  align-items: start;
  gap: 18px;
  padding: 18px 12px;
  border-radius: var(--radius-stack-card-mobile);
  color: inherit;
  text-decoration: none;
  transition: background-color 160ms ease, transform 160ms ease;
}
.sg-app::after {
  content: "";
  position: absolute;
  left: 86px;
  right: 12px;
  bottom: 0;
  height: 1px;
  background: var(--color-border);
}
.sg-apps-item:last-child .sg-app::after { display: none; }
a.sg-app:hover { background: var(--color-surface-soft); }
a.sg-app:active { transform: scale(0.99); }
a.sg-app:focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 2px; }
.sg-app-icon {
  padding: 2px !important;
  border-radius: var(--radius-stack-plan) !important;
  box-shadow: inset 0 0 0 1px var(--color-border);
}
.sg-app-body { display: flex; min-width: 0; flex-direction: column; gap: 3px; }
.sg-app-role {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--color-muted);
}
.sg-app-status {
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--color-chip);
  font-size: 11px;
  letter-spacing: 0;
  text-transform: none;
  color: var(--color-text);
}
.sg-app-name {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 18px;
  font-weight: 600;
  line-height: 1.3;
  color: var(--color-text-strong);
}
.sg-app-reason { font-size: 15px; line-height: 1.55; color: var(--color-text); }
.sg-app-tip { margin-top: 4px; font-size: 14px; line-height: 1.55; color: var(--color-muted); }
.sg-app-chevron { align-self: center; color: var(--color-muted); transition: transform 160ms ease; }
a.sg-app:hover .sg-app-chevron { transform: translateX(2px); color: var(--color-text); }

.sg-checks {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
  max-width: 860px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}
.sg-check {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr);
  gap: 14px;
  padding: 22px;
  border-radius: var(--radius-xl);
  background: var(--color-surface-soft);
}
.sg-check-index {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: var(--radius-circle);
  background: var(--color-surface);
  box-shadow: inset 0 0 0 1px var(--color-border);
  font-family: var(--font-ui);
  font-size: 14px;
  font-weight: 600;
}
.sg-check h3 { margin: 4px 0 10px; font-size: 17px; font-weight: 600; line-height: 1.35; }
.sg-check p { margin: 0; font-size: 15px; line-height: 1.6; color: var(--color-text); }

.sg-related {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr));
  gap: 16px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}
.sg-related-card {
  display: flex;
  height: 100%;
  flex-direction: column;
  gap: 18px;
  padding: 20px;
  border-radius: var(--radius-stack-card);
  box-shadow: inset 0 0 0 1px var(--color-border);
  color: inherit;
  text-decoration: none;
  transition: background-color 180ms ease, transform 180ms ease;
}
.sg-related-card:hover { background: var(--color-surface-soft); }
.sg-related-card:hover .sgs-folder { gap: 11px; background: var(--color-surface); transform: scale(1.03); }
.sg-related-card:active { transform: scale(0.99); }
.sg-related-card:focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 2px; }
.sg-related-copy { display: flex; flex-direction: column; gap: 6px; }
.sg-related-name { font-family: var(--font-ui); font-size: 17px; font-weight: 600; line-height: 1.3; color: var(--color-text-strong); }
.sg-related-sub {
  display: -webkit-box;
  overflow: hidden;
  font-size: 14px;
  line-height: 1.5;
  color: var(--color-muted);
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
}
@media (max-width: 700px) {
  .sg-app { grid-template-columns: 48px minmax(0, 1fr) 16px; gap: 14px; }
  .sg-app::after { left: 74px; }
  .sg-app-icon { width: 48px !important; height: 48px !important; min-width: 48px !important; min-height: 48px !important; }
}
@media (prefers-reduced-motion: reduce) {
  .sg-app, .sg-related-card, .sg-app-chevron { transition: none; }
  a.sg-app:active, .sg-related-card:active, .sg-related-card:hover .sgs-folder { transform: none; }
}

/* Stack hero: light ToolTrim panel, copy on the left, and the stack's apps
   once each, as a composed floating cluster on the right. */
.sg-hero--cluster {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 440px);
  align-items: center;
  gap: 48px;
  margin-top: 8px;
  padding: 56px 64px;
  overflow: hidden;
  border-radius: 36px;
  background: var(--color-surface-soft);
}
.sg-hero--cluster .sg-hero-copy { min-width: 0; }
.sg-hero-pill {
  display: inline-flex;
  margin-bottom: 22px;
  padding: 6px 12px;
  border-radius: 999px;
  background: var(--color-surface);
  box-shadow: inset 0 0 0 1px var(--color-border);
  font: 600 12px/1 var(--font-ui);
  letter-spacing: 0.04em;
  color: var(--color-text-strong);
}
.sg-hero--cluster h1 {
  max-width: 620px;
  font: 600 clamp(38px, 5vw, 72px)/0.98 var(--font-brand);
  letter-spacing: -0.05em;
  overflow-wrap: anywhere;
}
.sg-hero--cluster .sg-lead { max-width: 520px; margin: 22px 0 0; }
.sg-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  max-width: 520px;
  margin: 40px 0 0;
  padding-top: 22px;
  border-top: 1px solid var(--color-border);
}
.sg-stats > div { display: flex; min-width: 0; flex-direction: column; gap: 4px; padding: 0 16px; }
.sg-stats > div:first-child { padding-left: 0; }
.sg-stats > div + div { border-left: 1px solid var(--color-border); }
.sg-stats dt { font: 600 11px/1.3 var(--font-ui); letter-spacing: 0.08em; text-transform: uppercase; color: var(--color-muted); }
.sg-stats dd { margin: 0; font: 600 30px/1.1 var(--font-brand); letter-spacing: -0.03em; color: var(--color-text-strong); }
.sg-stats dd.sg-stats-word { font-size: 20px; line-height: 1.5; }
.sg-stats > div > span { font-size: 12px; color: var(--color-muted); }

.sg-cluster {
  position: relative;
  width: 100%;
  max-width: 440px;
  aspect-ratio: 440 / 380;
  justify-self: end;
}
.sg-cluster-app, .sg-cluster-more {
  position: absolute;
  display: grid;
  place-items: center;
  transform: translate(-50%, -50%) rotate(var(--r, 0deg));
  animation: sg-float 7s ease-in-out infinite;
  transition: filter 200ms ease;
}
.sg-cluster-app:hover { animation-play-state: paused; filter: drop-shadow(0 16px 24px rgb(0 0 0 / 0.16)); }
.sg-cluster-app:focus-visible, .sg-cluster-more:focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 4px; border-radius: 24%; }
.sg-cluster-icon {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  padding: 6% !important;
  border-radius: 24% !important;
  background: var(--color-surface) !important;
  box-shadow: 0 1px 0 rgb(0 0 0 / 0.04), 0 12px 28px rgb(0 0 0 / 0.08), inset 0 0 0 1px var(--color-border) !important;
}
.sg-cluster-more {
  width: 50px;
  height: 50px;
  border-radius: var(--radius-stack-plan);
  background: var(--color-surface);
  box-shadow: inset 0 0 0 1px var(--color-border);
  font: 600 15px/1 var(--font-ui);
  color: var(--color-muted);
  text-decoration: none;
}
@keyframes sg-float {
  0%, 100% { transform: translate(-50%, -50%) rotate(var(--r, 0deg)); }
  50% { transform: translate(-50%, calc(-50% - 6px)) rotate(var(--r, 0deg)); }
}

@media (max-width: 1100px) and (min-width: 901px) {
  .sg-hero--cluster { grid-template-columns: minmax(0, 1fr) minmax(0, 340px); padding: 48px; gap: 32px; }
}
@media (max-width: 900px) {
  .sg-hero--cluster { grid-template-columns: minmax(0, 1fr); gap: 28px; padding: 36px 28px 28px; border-radius: var(--radius-2xl); }
  .sg-cluster { justify-self: center; max-width: 340px; }
}
@media (max-width: 640px) {
  .sg-hero--cluster { margin-inline: -8px; padding: 30px 22px 22px; }
  .sg-stats dd { font-size: 24px; }
  .sg-stats dd.sg-stats-word { font-size: 16px; }
  .sg-stats > div { padding: 0 10px; }
}
@media (prefers-reduced-motion: reduce) {
  .sg-cluster-app, .sg-cluster-more { animation: none; }
}

/* Budget: two figures, then one bar per tool (Screen Time style). */
.sg-budget-card {
  padding: 32px;
  border-radius: var(--radius-2xl);
  background: var(--color-surface-soft);
}
.sg-budget-figures {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 220px), 1fr));
  gap: 24px 48px;
  padding-bottom: 28px;
  border-bottom: 1px solid var(--color-border);
}
.sg-budget-figure { display: flex; flex-direction: column; gap: 4px; }
.sg-budget-figure > span {
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-muted);
}
.sg-budget-figure strong {
  font: 600 clamp(40px, 5vw, 56px)/1 var(--font-brand);
  letter-spacing: -0.045em;
  color: var(--color-muted);
}
.sg-budget-figure--target strong { color: var(--color-text-strong); }
.sg-budget-figure small { font-size: 13px; color: var(--color-muted); }
.sg-storage { margin-top: 32px; }
.sg-storage-bar {
  position: relative;
  display: flex;
  height: 28px;
  gap: 2px;
  padding: 3px;
  border-radius: var(--radius-md);
  background: var(--color-surface);
  box-shadow: inset 0 0 0 1px var(--color-border);
}
.sg-storage-seg {
  display: block;
  min-width: 6px;
  height: 100%;
  background: var(--color-text-strong);
  transform-origin: left;
  animation: sg-bar-grow 700ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.sg-storage-seg:first-child { border-radius: var(--radius-stack-pair-logo) 0 0 var(--radius-stack-pair-logo); }
.sg-storage-seg:nth-last-child(2), .sg-storage-seg:last-child { border-radius: 0 var(--radius-stack-pair-logo) var(--radius-stack-pair-logo) 0; }
.sg-storage-seg:only-of-type { border-radius: var(--radius-stack-pair-logo); }
.sg-storage-target {
  position: absolute;
  top: -8px;
  bottom: -8px;
  width: 2px;
  margin-left: -1px;
  border-radius: var(--radius-2xs);
  background: #D93A2B;
  box-shadow: 0 0 0 2px var(--color-surface-soft);
}
.sg-storage-target > span {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 50%;
  padding: 4px 8px;
  border-radius: 999px;
  background: #D93A2B;
  color: var(--color-bg);
  font: 600 12px/1 var(--font-ui);
  white-space: nowrap;
  transform: translateX(-50%);
}
.sg-storage-scale {
  display: flex;
  justify-content: space-between;
  margin-top: 8px;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: var(--color-muted);
}
.sg-storage-legend {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 210px), 1fr));
  gap: 12px 28px;
  margin: 28px 0 0;
  padding: 0;
  list-style: none;
}
.sg-storage-legend li {
  display: grid;
  grid-template-columns: 8px 24px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
}
.sg-storage-legend li.is-muted .sg-budget-logo { opacity: 0.55; }
.sg-storage-legend li.is-muted .sg-budget-value { font-weight: 400; color: var(--color-muted); }
.sg-storage-dot { width: 8px; height: 8px; border-radius: var(--radius-circle); background: var(--color-text-strong); }
.sg-storage-dot--empty { background: none; box-shadow: inset 0 0 0 1px var(--color-border); }
.sg-budget-logo { padding: 1px !important; border-radius: 7px !important; box-shadow: inset 0 0 0 1px var(--color-border); }
.sg-budget-name { overflow: hidden; font-size: 14px; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
.sg-budget-name em { margin-left: 6px; font-size: 12px; font-style: normal; font-weight: 400; color: var(--color-muted); }
.sg-budget-value { font-size: 14px; font-weight: 600; font-variant-numeric: tabular-nums; text-align: right; }
.sg-budget-note { max-width: 760px; margin: 24px 0 0; font-size: 13px; line-height: 1.6; color: var(--color-muted); }
@keyframes sg-bar-grow { from { transform: scaleX(0); } to { transform: scaleX(1); } }

/* Trade-offs: the trap as a high-contrast card, then a quiet watch list. */
.sg-risk-card {
  display: grid;
  gap: 12px;
  padding: 36px 40px;
  border-radius: var(--radius-2xl);
  background: var(--color-ink);
  color: var(--color-bg);
}
.sg-risk-card svg { color: var(--color-bg); opacity: 0.8; }
.sg-risk-label {
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0.65;
}
.sg-risk-card p {
  max-width: 820px;
  margin: 0;
  font: 500 clamp(21px, 2.4vw, 28px)/1.35 var(--font-brand);
  letter-spacing: -0.02em;
}
.sg-watch {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
  gap: 12px 32px;
  margin: 28px 0 0;
  padding: 0;
  list-style: none;
}
.sg-watch li {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  gap: 14px;
  padding-top: 20px;
  border-top: 1px solid var(--color-border);
}
.sg-watch li > svg { margin-top: 3px; color: var(--color-muted); }
.sg-watch h3 { margin: 0 0 8px; font-size: 16px; font-weight: 600; line-height: 1.35; }
.sg-watch p { margin: 0; font-size: 15px; line-height: 1.6; }
.sg-watch .sg-watch-reco { margin-top: 10px; color: var(--color-muted); }

@media (max-width: 640px) {
  .sg-stats dd { font-size: 22px; }
  .sg-stats dd.sg-stats-word { font-size: 16px; }
  .sg-budget-card { padding: 22px; border-radius: var(--radius-stack-card); }
  .sg-risk-card { padding: 26px 24px; border-radius: var(--radius-stack-card); }
}
@media (prefers-reduced-motion: reduce) {
  .sg-storage-seg { animation: none; }
}

/* Budget card: iOS segmented switch between the ring and the gap bar. */
.sg-budget-switch {
  display: inline-flex;
  gap: 2px;
  margin-top: 28px;
  padding: 3px;
  border-radius: var(--radius-md);
  background: var(--color-surface);
  box-shadow: inset 0 0 0 1px var(--color-border);
}
.sg-budget-switch-tab {
  padding: 7px 14px;
  border: 0;
  border-radius: var(--radius-stack-pair-logo);
  background: transparent;
  font: 600 13px/1 var(--font-ui);
  color: var(--color-muted);
  cursor: pointer;
  transition: background-color 160ms ease, color 160ms ease;
}
.sg-budget-switch-tab[aria-selected="true"] { background: var(--color-text-strong); color: var(--color-surface); }
.sg-budget-switch-tab:focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 2px; }
.sg-budget-viz { margin-top: 8px; }
.sg-budget-viz--share {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  align-items: center;
  gap: 40px;
  margin-top: 24px;
}
.sg-budget-viz--share .sg-storage-legend { margin-top: 0; grid-template-columns: repeat(auto-fill, minmax(min(100%, 200px), 1fr)); }
.sg-donut { width: 220px; height: 220px; overflow: visible; }
.sg-donut-seg {
  stroke: var(--color-text-strong);
  cursor: pointer;
  transition: opacity 180ms ease, stroke-width 180ms ease;
  animation: sg-donut-in 800ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.sg-donut-seg.is-dim { opacity: 0.12 !important; }
.sg-donut-seg.is-focus { stroke-width: 32; }
.sg-donut-value { font: 600 30px/1 var(--font-brand); letter-spacing: -0.03em; fill: var(--color-text-strong); }
.sg-donut-label { font: 500 11px/1 var(--font-ui); fill: var(--color-muted); }
@keyframes sg-donut-in { from { stroke-dasharray: 0 999; } }
.sg-storage-seg.is-dim { opacity: 0.12 !important; }
.sg-storage-legend li { border-radius: var(--radius); transition: opacity 160ms ease; }
.sg-storage-legend li.is-dim { opacity: 0.4; }
.sg-storage-legend li.is-focus .sg-budget-name { text-decoration: underline; text-underline-offset: 3px; }
@media (max-width: 700px) {
  .sg-budget-viz--share { grid-template-columns: 1fr; justify-items: center; gap: 24px; }
  .sg-budget-viz--share .sg-storage-legend { width: 100%; }
}
@media (prefers-reduced-motion: reduce) {
  .sg-donut-seg { animation: none; transition: none; }
}

/* Stack page: blocks are cards now, so sections are separated by space,
   not hairlines. */
.sg-page .sg-section { border-top: 0; padding-block: 56px 0; }
.sg-page .sg-hero--cluster + .sg-section { padding-top: 64px; }
@media (max-width: 700px) {
  .sg-page .sg-section { padding-block: 40px 0; }
}
.sg-page .sg-insights { gap: 12px; }
.sg-page .sg-insights > div,
.sg-page .sg-watch li {
  padding: 22px;
  border-top: 0;
  border-radius: var(--radius-xl);
  background: var(--color-surface-soft);
}
.sg-page .sg-watch { gap: 12px; }

/* ── Stacks index, App Store pass: featured band + two-column list ─────── */
.sk-group-title {
  margin: 36px 0 14px;
  font: 600 22px/1.2 var(--font-brand);
  letter-spacing: -0.02em;
  color: var(--color-text-strong);
}
.sk-featured-grid, .sk-list { margin: 0; padding: 0; list-style: none; }
.sk-featured-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}
.sk-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: 40px;
  margin-inline: -12px;
}
.sk-row {
  position: relative;
  display: grid;
  grid-template-columns: 76px minmax(0, 1fr);
  align-items: center;
  gap: 18px;
  height: 100%;
  padding: 14px 12px;
  border-radius: var(--radius-xl);
  color: inherit;
  text-decoration: none;
  transition: background-color 160ms ease, transform 160ms ease;
}
.sk-list .sk-row::after {
  content: "";
  position: absolute;
  left: 106px;
  right: 12px;
  bottom: 0;
  height: 1px;
  background: var(--color-border);
}
.sk-list li:last-child .sk-row::after { display: none; }
@media (min-width: 900px) {
  .sk-list li:nth-last-child(2):nth-child(odd) .sk-row::after { display: none; }
}
.sk-row:hover { background: var(--color-surface-soft); }
.sk-row:hover .sk-row-folder { gap: 9px; background: var(--color-surface); transform: scale(1.03); }
.sk-row:active { transform: scale(0.99); }
.sk-row:focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 2px; }
.sk-row-folder {
  width: 76px !important;
  height: 76px !important;
  grid-template-columns: repeat(2, 26px) !important;
  grid-template-rows: repeat(2, 26px) !important;
  gap: 7px !important;
  border-radius: 21px !important;
}
.sk-row-folder .sgs-folder-logo { width: 26px !important; height: 26px !important; min-width: 26px !important; min-height: 26px !important; border-radius: 7px !important; }
.sk-row-copy { display: flex; min-width: 0; flex-direction: column; gap: 2px; }
.sk-row-persona {
  font: 600 11px/1.3 var(--font-ui);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-muted);
}
.sk-row-title { font: 600 17px/1.3 var(--font-ui); color: var(--color-text-strong); }
.sk-row-sub {
  overflow: hidden;
  font-size: 14px;
  line-height: 1.45;
  color: var(--color-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sk-row-meta {
  display: flex;
  gap: 6px;
  margin-top: 4px;
  font-size: 13px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--color-text);
}
.sk-row-meta > span { color: var(--color-muted); font-weight: 400; }

/* Featured: the same row, stacked into a tile with a larger folder. */
.sk-row--featured {
  grid-template-columns: 1fr;
  align-content: start;
  gap: 18px;
  padding: 22px;
  background: var(--color-surface-soft);
  border-radius: var(--radius-surface);
}
.sk-row--featured:hover { background: color-mix(in srgb, var(--color-surface-soft) 70%, var(--color-border)); }
.sk-row--featured .sk-row-folder {
