.td-tool-page .td-hero-logo { background: var(--tool-accent-soft, var(--color-surface)); border-color: var(--tool-accent-line, var(--color-border)); }
.td-tool-page .td-tool-subnav a:is([aria-current="page"], [aria-current="location"]) { color: var(--tool-accent-ink, var(--color-text)); }
.td-tool-page .td-localnav-links a:is([aria-current="page"], [aria-current="location"]),
.td-tool-page .td-localnav-links a:hover,
.td-tool-page .td-localnav .pin-tool-button:hover,
.td-tool-page .td-localnav-title:hover > span:last-child { color: var(--tool-accent-ink, hsl(var(--primary))); }
.td-tool-page .td-localnav-links a:is([aria-current="page"], [aria-current="location"])::after { background: var(--tool-accent-ink, hsl(var(--primary))); }
.td-tool-page .td-localnav-logo { border-radius: var(--radius); background: var(--tool-accent-soft, transparent); box-shadow: inset 0 0 0 1px var(--tool-accent-line, transparent); }
.td-tool-page .td-eyebrow { color: var(--tool-accent-ink, var(--color-muted)); }
.td-tool-page .td-plan--reference { border-color: var(--tool-accent-ink, var(--color-text)); }
.td-tool-page .td-plan-badge { background: var(--tool-accent-ink, var(--color-text)); }
/* ── Fiche outil : rythme éditorial (2 oct.) ──
   Chapitres plus aérés et titres un peu plus présents, toujours sous le nom
   de l'outil (40-56 px). Tous les titres suivent la même grammaire :
   « Sujet. Question en gris ». */
.td-tool-page { --tt-size-section-h: clamp(26px, 2.7vw, 38px); }
