@media (max-width: 640px) { .td-tool-page .td-hero:not(.is-compact) .td-stack-note { grid-column: 1 / -1; } }
/* Stack vide : trois étapes, numérotées, sans suggestion d'outils. */
.ms-page .ms-howto { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; max-width: 980px; margin: 40px 0 0; padding: 0; list-style: none; counter-reset: ms-howto; }
.ms-page .ms-howto li { display: grid; gap: 6px; padding: 20px; border: 1px solid hsl(var(--border)); border-radius: var(--radius-lg); background: hsl(var(--card)); counter-increment: ms-howto; }
.ms-page .ms-howto li::before { content: counter(ms-howto); display: grid; place-items: center; width: 28px; height: 28px; margin-bottom: 6px; border-radius: var(--radius-circle); background: hsl(var(--foreground)); color: hsl(var(--background)); font: 600 13px/1 var(--font-ui); }
