  .tt-footer .tt-footer-badges { display: flex; flex-wrap: nowrap; gap: 18px; overflow-x: auto; scrollbar-width: none; -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 40px), transparent); mask-image: linear-gradient(90deg, #000 calc(100% - 40px), transparent); }
  .tt-footer .tt-footer-badges::-webkit-scrollbar { display: none; }
