/* Footer twist: the tagline acted out. A pile of five same-job tools, trimmed
   to one when the footer comes into view; hover reopens the pile. */
.tt-trim { --ease: cubic-bezier(.34, 1.3, .64, 1); display: inline-flex; vertical-align: middle; margin: -6px 0 0 18px; }
.tt-trim-pile { position: relative; width: 84px; height: 52px; }
.tt-trim-tile { position: absolute; left: 0; top: 6px; display: block; width: 40px; height: 40px; border-radius: var(--radius-stack-logo-mobile); background: var(--tt-footer-card); box-shadow: 0 0 0 1px rgba(15, 15, 15, .06), 0 2px 6px rgba(15, 15, 15, .08); overflow: hidden;
  transform: translate(calc(var(--i) * 10px), calc(var(--i) * -1.5px)) rotate(var(--r));
  transition: transform 380ms var(--ease) calc(var(--i) * 25ms), opacity 140ms cubic-bezier(0, 0, .2, 1) calc(var(--i) * 25ms); z-index: var(--i); }
/* Each tile's place in the pile: its index and tilt (static, so in CSS
   rather than inline styles). */
.tt-trim-tile:nth-child(1) { --i: 0; --r: -7deg; }
.tt-trim-tile:nth-child(2) { --i: 1; --r: 5deg; }
.tt-trim-tile:nth-child(3) { --i: 2; --r: -3deg; }
.tt-trim-tile:nth-child(4) { --i: 3; --r: 8deg; }
.tt-trim-tile:nth-child(5) { --i: 4; --r: -5deg; }
.tt-trim-tile > * { width: 100% !important; height: 100% !important; border-radius: inherit; }
.tt-trim[data-trimmed] .tt-trim-tile { transform: translate(22px, 0) rotate(0deg) scale(.6); opacity: 0; transition: transform 380ms var(--ease) calc((4 - var(--i)) * 25ms), opacity 220ms ease calc(140ms + (4 - var(--i)) * 25ms); }
/* The one kept: a neutral white tile with an ink check, never a brand, and
   never a second black block next to the primary button. */
.tt-trim-one { position: absolute; left: 22px; top: 6px; z-index: 10; display: grid; place-items: center; width: 40px; height: 40px; border-radius: var(--radius-stack-logo-mobile); background: var(--tt-footer-card); color: var(--tt-footer-ink); box-shadow: 0 0 0 1px rgba(15, 15, 15, .06), 0 4px 14px rgba(15, 15, 15, .10); opacity: 0; transform: scale(.7) rotate(-6deg); transition: transform 380ms var(--ease), opacity 160ms ease; }
.tt-trim-one path { stroke-dasharray: 16; stroke-dashoffset: 16; transition: stroke-dashoffset 240ms ease; }
.tt-trim[data-trimmed] .tt-trim-one { opacity: 1; transform: none; transition-delay: 160ms; }
.tt-trim[data-trimmed] .tt-trim-one path { stroke-dashoffset: 0; transition-delay: 340ms; }
@media (prefers-reduced-motion: reduce) { .tt-trim *, .tt-trim *::before { transition: none !important; } }
@media (max-width: 640px) { .tt-trim { margin-left: 12px; transform: scale(.85); transform-origin: left center; } }

