.home-v2 .sgs-item { gap: var(--space-xl); padding: var(--space-lg) var(--space-lg) var(--space-xl); border-radius: var(--radius-2xl); background: var(--color-surface-soft); box-shadow: none; transition: background-color 260ms ease, transform 260ms cubic-bezier(.25, 1, .5, 1); }
.home-v2 .sgs-item:hover { background: var(--color-surface-soft); box-shadow: none; transform: translateY(-3px); }
.home-v2 .sgs-folder { background: var(--color-surface); box-shadow: 0 1px 2px rgb(0 0 0 / .05), 0 10px 24px -14px rgb(0 0 0 / .18); }
.home-v2 .sgs-item:hover .sgs-folder { background: var(--color-surface); }
.home-v2 .sgs-folder-logo { box-shadow: 0 0 0 .5px rgb(0 0 0 / .06) !important; }
.home-v2 .sgs-item-objective { margin-bottom: var(--space-xs); color: var(--h-ink); font: 330 11.5px/1.4 var(--font-ui); letter-spacing: .16em; text-transform: uppercase; }
.home-v2 .sgs-item-title { margin-top: 0; font: 500 21px/1.2 var(--font-brand); letter-spacing: -.02em; color: var(--h-ink); }
.home-v2 .sgs-item-subtitle { margin-top: var(--space-xs); color: var(--h-ink); font: 400 15px/1.45 var(--font-ui); }
.home-v2 .sgs-item:focus-visible { outline: 2px solid var(--h-ink); outline-offset: 3px; }
.dark .home-v2 .sgs-folder, .dark .home-v2 .sgs-item:hover .sgs-folder { background: var(--color-chip); box-shadow: inset 0 0 0 1px var(--color-border); }
@media (prefers-reduced-motion: reduce) { .home-v2 .sgs-item, .home-v2 .sgs-item:hover { transition: none; transform: none; } }

/* Comparisons: four whole tiles on a grid (no cut carousel), the duel on a
   cool grey tile, the question in the display face. Needs keep their three
   picks: reference, ToolTrim pick, discovery.
   More air between sections, as recommended. */
.home-v2 { --h-gap: clamp(96px, 9vw, 140px); }
.home-v2 .hc-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--space-lg) var(--space-sm); margin: 0; padding: 0; list-style: none; }
.home-v2 .hc-duel { border-radius: var(--radius-2xl); }
.home-v2 .hc-title { margin-top: var(--space-md); font: 500 21px/1.2 var(--font-brand); letter-spacing: -.02em; color: var(--h-ink); }
.home-v2 .hc-summary { margin-top: var(--space-xs); color: var(--h-ink); }
@media (max-width: 1100px) { .home-v2 .hc-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 640px) {
  .home-v2 .hc-grid { position: relative; display: flex; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; margin-inline: calc(-1 * var(--v2-grid-gutter)); padding-inline: var(--v2-grid-gutter); scroll-padding-inline: var(--v2-grid-gutter); }
  .home-v2 .hc-grid::-webkit-scrollbar { display: none; }
