@layer components {
  .sp-pitch-copy > * { animation: sp-rise .7s cubic-bezier(.2,.7,.2,1) both; }
  .sp-pitch-copy > :nth-child(2) { animation-delay: .06s; }
  .sp-pitch-copy > :nth-child(3) { animation-delay: .14s; }
  .sp-pitch-copy > :nth-child(n+4) { animation-delay: .22s; }
  .sp-pitch h1 { font-size: clamp(2.5rem, 4.6vw, 4.25rem); line-height: 1.02; letter-spacing: -.045em; }

  .sp-hero-visual { position: relative; padding: var(--space-2xl) var(--space-lg); perspective: 1600px; animation: sp-rise .9s .18s cubic-bezier(.2,.7,.2,1) both; }
  .sp-shot { overflow: hidden; background: var(--color-surface); border: 1px solid var(--color-border); border-radius: var(--radius-xl); box-shadow: 0 1px 2px rgb(0 0 0 / .04), 0 24px 48px -12px rgb(0 0 0 / .18), 0 60px 120px -40px rgb(0 0 0 / .22); transform: rotateY(-9deg) rotateX(4deg); transform-origin: 60% 50%; transition: transform .6s cubic-bezier(.2,.7,.2,1); }
  .sp-hero-visual:hover .sp-shot { transform: rotateY(-3deg) rotateX(1deg); }
  .sp-shot-bar { display: flex; align-items: center; gap: 6px; padding: 12px 14px; border-bottom: 1px solid var(--color-border); background: var(--color-surface-soft); }
  .sp-shot-bar > span { width: 9px; height: 9px; border-radius: var(--radius-circle); background: var(--color-border); }
  .sp-shot-bar em { flex: 1; margin-left: 10px; padding: 4px 10px; overflow: hidden; border-radius: var(--radius-pill); background: var(--color-surface); font: 500 11px/1.4 var(--font-ui); font-style: normal; color: var(--color-text-meta); white-space: nowrap; text-overflow: ellipsis; }
  .sp-shot-body { display: grid; gap: 18px; padding: 22px; }
  .sp-shot-identity { display: flex; align-items: center; gap: 14px; }
  .sp-shot-identity strong { display: block; font: 600 20px/1.2 var(--font-brand); letter-spacing: -.02em; color: var(--color-text); }
  .sp-shot-status { display: inline-flex; align-items: center; gap: 7px; margin-top: 4px; font: 500 12px/1.4 var(--font-ui); color: var(--color-text-meta); }
  .sp-shot-status i { width: 7px; height: 7px; border-radius: var(--radius-circle); background: var(--color-text); animation: sp-pulse 1.6s ease-in-out infinite; }
  .sp-shot-tabs { display: flex; gap: 6px; }
  .sp-shot-tabs span { padding: 5px 11px; border-radius: var(--radius-pill); background: var(--color-surface-soft); font: 500 11px/1.3 var(--font-ui); color: var(--color-text-secondary); }
  .sp-shot-tabs span:first-child { background: var(--color-text); color: var(--color-bg); }
  .sp-shot-lines { display: grid; gap: 9px; }
  .sp-shot-lines span { height: 9px; border-radius: var(--radius-pill); background: var(--color-surface-soft); transform-origin: left; animation: sp-write 3.2s cubic-bezier(.4,0,.2,1) infinite; }
  .sp-shot-lines span:nth-child(2) { width: 88%; animation-delay: .35s; }
  .sp-shot-lines span:nth-child(3) { width: 62%; animation-delay: .7s; }
  .sp-shot-score { display: flex; align-items: baseline; justify-content: space-between; padding-top: 14px; border-top: 1px solid var(--color-border); font: 600 13px/1.3 var(--font-ui); color: var(--color-text); }
  .sp-shot-score em { font: 500 12px/1.3 var(--font-ui); font-style: normal; color: var(--color-text-meta); }
  .sp-shot-cta { justify-self: start; padding: 9px 16px; border-radius: var(--radius-pill); background: var(--color-text); font: 600 12px/1 var(--font-ui); color: var(--color-bg); }

  .sp-orbit { position: absolute; display: inline-flex; align-items: center; gap: 7px; padding: 9px 14px; border: 1px solid var(--color-border); border-radius: var(--radius-pill); background: var(--color-surface); box-shadow: 0 12px 28px -10px rgb(0 0 0 / .2); font: 500 12px/1 var(--font-ui); color: var(--color-text-secondary); white-space: nowrap; animation: sp-float 6s ease-in-out infinite; }
  .sp-orbit strong { font: 700 14px/1 var(--font-brand); color: var(--color-text); }
  .sp-orbit svg { color: var(--color-text); }
  .sp-orbit--dr { top: 8px; left: -6px; }
  .sp-orbit--link { top: 46%; right: -14px; animation-delay: -2s; }
  .sp-orbit--time { bottom: 10px; left: 12%; animation-delay: -4s; }

  @keyframes sp-rise { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
  @keyframes sp-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-7px); } }
