@layer components {
  /* Micro-animation pass (2026-10-16): feedback on every gesture, 100-250ms,
     transform/opacity only, nothing under reduced motion. */
  @media (prefers-reduced-motion: no-preference) {
    /* 1 · Press feedback on the page's buttons. */
    .td-tool-page :is(.td-hero-site-link, .td-hero-actions .pin-tool-button, .td-localnav-cta, .td-decision-compare, .td-decision-cta-main, .td-explore-map-btn, .tg-hero-arrow, .td-fit-switch-btn) {
      transition-property: transform, background-color, box-shadow, color;
      transition-duration: 160ms; transition-timing-function: cubic-bezier(0.2, 0.8, 0.2, 1);
    }
    .td-tool-page :is(.td-hero-site-link, .td-hero-actions .pin-tool-button, .td-localnav-cta, .td-decision-compare, .td-decision-cta-main, .td-explore-map-btn, .td-fit-switch-btn):active { transform: scale(0.97); }

    /* 2 · Bookmark pops when the tool is added to the stack. */
    .td-tool-page .pin-tool-button--active svg { animation: td-pin-pop 360ms cubic-bezier(0.34, 1.56, 0.64, 1); }
    @keyframes td-pin-pop { 0% { transform: scale(0.6); } 60% { transform: scale(1.18); } 100% { transform: scale(1); } }

    /* 3 · Tab underline grows from the centre when a tab becomes active
       (also while reading, as the overview tab follows the section). */
    .td-tool-page :is(.td-tool-subnav, .td-localnav-links) a:is([aria-current="page"], [aria-current="location"])::after {
      animation: td-tab-grow 240ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
    }
    @keyframes td-tab-grow { from { transform: scaleX(0); } to { transform: scaleX(1); } }

    /* 4 · FAQ: the answer fades in, the marker turns. */
    .td-tool-page details > summary::after { display: inline-block; transition: transform 200ms cubic-bezier(0.2, 0.8, 0.2, 1); }
    .td-tool-page details[open] > summary::after { transform: rotate(180deg); }
    .td-tool-page details[open] > :not(summary) { animation: td-faq-in 240ms cubic-bezier(0.2, 0.8, 0.2, 1) both; }
    @keyframes td-faq-in { from { opacity: 0; transform: translateY(-4px); } }

    /* 5 · Slider thumb grows while held. */
    .td-breakeven-control input[type="range"]::-webkit-slider-thumb { transition: transform 140ms ease-out; }
    .td-breakeven-control input[type="range"]:active::-webkit-slider-thumb { transform: scale(1.25); }
    .td-breakeven-control input[type="range"]::-moz-range-thumb { transition: transform 140ms ease-out; }
    .td-breakeven-control input[type="range"]:active::-moz-range-thumb { transform: scale(1.25); }

    /* 6 · Alternative cards lift on hover. */
    .td-tool-page .td-compare .td-alt-card { transition: background-color 160ms ease-out, transform 200ms cubic-bezier(0.2, 0.8, 0.2, 1); }
    .td-tool-page .td-compare .td-alt-card:hover { transform: translateY(-2px); }
  }
}

@layer components {
