.ex-tool-focus-content > p { color: color-mix(in srgb, var(--color-text) 74%, transparent); font-size: var(--tt-size-section-intro); line-height: 1.45; margin-top: 18px; max-width: 44ch; text-wrap: pretty; }
.ex-tool-focus-footer { flex-wrap: wrap; gap: 10px; margin-top: 24px; }
.ex-tool-focus-profile, .ex-tool-focus-add { border-radius: var(--radius-pill); font-size: 14px; font-weight: 600; min-height: 44px; padding: 0 18px; white-space: nowrap; }
.ex-tool-focus-add { border: 1px solid color-mix(in srgb, var(--color-text) 18%, transparent); }
.ex-tool-focus-add:hover:not(:disabled) { background: transparent; border-color: var(--color-text); }
@media (max-width: 960px) {
  .ex-tool-focus-main { gap: 20px; grid-template-columns: minmax(0, 1fr); padding: 0; }
  .ex-tool-focus-content { padding: 0 4px; }
